    "difficulty": 3,
    "question": "問7\n ア~エを比較して,著作隣接権制度に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "実演家とレコード製作者は,商業用レコードを用いた放送又は有線放送を行った場合の二次\n  使用料を受ける権利を有する。",
      "イ": "レコード製作者とは,レコードを発行した者をいう。",
      "ウ": "実演家は公表権を有するため,その実演を無断で公表された場合,公表を差し止めることが\n  できる。",
      "エ": "放送事業者は,複製権は有しないが,送信可能化権は有する。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "商業用レコードを放送等に使う場合、実演家とレコード製作者に二次使用料を受ける権利が認められる。隣接権の主体ごとに権利内容が異なる点を押さえてアを選ぶ。",
    "basis": "著作権法2条・90条の2・90条の3・95条・97条・98条・99条の2",
    "choiceExplanations": {
      "ア": "商業用レコードの放送・有線放送について、実演家とレコード製作者に二次使用料の制度がある。",
      "イ": "レコード製作者は音を最初に固定した者。レコードの発行者と同義ではない。",
      "ウ": "実演家人格権は氏名表示権・同一性保持権。著作者と同じ公表権があるとはいえない。",
      "エ": "放送事業者は放送の複製権も有する。送信可能化権だけではない。"
    },
