    "difficulty": 3,
    "question": "問8\n ア~エを比較して,契約に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "売買契約の当事者が相手方と通じて真意ではなく売買契約をしたとしても,善意の第三者に\n  対して売買契約が無効であると主張できない。",
      "イ": "意思表示に錯誤があった場合,その錯誤が法律行為の目的及び取引上の社会通念に照らして\n  重要なものであるときは,その意思表示を取り消すことができる。",
      "ウ": "契約不適合責任は,民法上定められた規定であるので,当事者間の契約によって,排除する\n  ことはできない。",
      "エ": "契約は申込みと承諾の意思表示が合致した時に成立するので,口頭による契約であっても無\n  効とはならない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "契約不適合責任の規定には当事者間の特約が可能であり、すべて強行規定ではない。排除できないと断定するウが不適切。ただし知りながら告げなかった事実等には免責の制限がある。",
    "basis": "民法94条・95条・522条・572条",
    "choiceExplanations": {
      "ア": "通謀虚偽表示による無効を善意の第三者に対抗することはできない。",
      "イ": "法律行為の目的・取引上の社会通念に照らして重要な錯誤は取消しの対象となる。",
      "ウ": "責任の変更・排除を定める特約は可能。免責特約があっても免責されない場合までなくなるわけではない。",
      "エ": "原則として申込みと承諾の合致で成立し、書面を要する特別な場合を除けば口頭でも契約は成立する。"
    },
    "explanationCoverage": "full",
