    "difficulty": 3,
    "question": "問9\n ア~エを比較して,種苗法に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "育成者権の存続期間は登録の日から10年間であるが,申請により存続期間を更新すること\n  ができる。",
      "イ": "育成者権者により登録品種の種苗が譲渡された場合には,その種苗を用いていかなる地域で\n  収穫物が生産されたとしても,育成者権の効力は及ばない。",
      "ウ": "品種登録を受けるためには,均一性,安定性,区別性及び未譲渡性の要件を満たすことが必\n  要である。",
      "エ": "育成者権の効力は,農業者が登録品種に係る収穫物の一部を次の作付けの種苗として使用す\n  る行為に対して及ばない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "品種登録では区別性・均一性・安定性・未譲渡性等を確認する。地域制限や自家増殖に関する制度を無視する肢は適切でなく、ウを選ぶ。",
    "basis": "種苗法3条・19条・21条等",
    "choiceExplanations": {
      "ア": "育成者権は原則登録から25年、永年性植物は30年。10年ごとの更新制度ではない。",
      "イ": "国内栽培地域等の指定に反する利用など、譲渡後も権利が及ぶ場合がある。『いかなる地域でも』は誤り。",
      "ウ": "他品種と区別でき、個体間で十分に均一で、繰返し増殖しても特性が安定し、所定の未譲渡性を満たす必要がある。",
      "エ": "登録品種の自家増殖は原則として育成者権者の許諾が必要。農業者だから一律に自由とはいえない。"
    },
