    "difficulty": 3,
    "question": "問10\n ア~エを比較して,パリ条約に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "同盟国の国民は,内国民に課される条件及び手続に従う限り,内国民と同一の保護を受け,\n  かつ,自己の権利の侵害に対し内国民と同一の法律上の救済を与えられる。",
      "イ": "司法上及び行政上の手続並びに裁判管轄権については,各同盟国の法令の定めるところによ\n  る。",
      "ウ": "同盟国の国民が工業所有権を享有するためには,保護が請求される国に住所又は営業所を有\n  することが条件とされる。",
      "エ": "各同盟国の国民は,工業所有権の保護に関し,この条約で特に定める権利を害されることな\n  く,他のすべての同盟国において,当該他の同盟国の法令が内国民に対し現在与えており又\n  は将来与えることがある利益を享受する。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "内国民待遇を受けるために、保護を求める同盟国に住所や営業所を置く必要はない。ウはこの原則に反するため、最も不適切。",
    "basis": "パリ条約2条",
    "choiceExplanations": {
      "ア": "同盟国の国民は原則として内国民と同じ保護・救済を受ける。国内の条件・手続は遵守する。",
      "イ": "司法・行政手続や裁判管轄については、条約で留保された各国の法令による。",
      "ウ": "住所又は営業所を保護請求国に持つことを権利享有の条件にはできない。",
      "エ": "内国民待遇により、条約固有の権利を害さず、その国が内国民に与える利益を享受する。"
    },
