      "イ": "国内優先権の主張を伴う特許出願に係る特許権の存続期間は,先の出願の日から20年を\n  もって終了する。",
      "ウ": "国内優先権の主張を伴う特許出願は,先の出願の日から1年6カ月を経過したときに出願公\n  開される。",
