    "difficulty": 3,
    "question": "問13\n ア~エを比較して,意匠法に規定される法目的に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "経済及び産業の発展に資すること",
      "イ": "文化の発展に寄与すること",
      "ウ": "産業の発達に寄与すること",
      "エ": "需要者の利益を保護すること"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "意匠法は意匠の保護・利用により創作を奨励し、産業の発達に寄与することを目的とする。条文の目的を問うのでウを選ぶ。",
    "basis": "意匠法1条",
    "choiceExplanations": {
      "ア": "意匠法1条の目的の表現は『産業の発達に寄与』であり、この肢の表現ではない。",
      "イ": "文化の発展への寄与は著作権法の目的に対応する。",
      "ウ": "意匠法1条に定める目的に一致する。",
      "エ": "需要者の利益の保護は商標法の目的に含まれる表現である。"
    },
