    "difficulty": 3,
    "question": "問14\n ア~エを比較して,著作権法上の保護の対象となる著作物として,最も不適切と考えられるも\nのはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "無言劇",
      "イ": "建築",
      "ウ": "講演",
      "エ": "プログラム言語"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "著作物として例示される無言劇、建築、講演に対し、プログラム言語それ自体にはプログラム著作物の保護が及ばない。エが不適切。",
    "basis": "著作権法10条1項・3項",
    "choiceExplanations": {
      "ア": "舞踊又は無言劇は著作物の例示に含まれ、創作性等を満たせば保護される。",
      "イ": "建築の著作物は保護対象の例示に含まれる。すべての建造物が自動的に該当するわけではない。",
      "ウ": "講演は言語の著作物として保護され得る。",
      "エ": "プログラム言語は、規約・解法とともにプログラム著作物の保護の対象から除かれる。個別のプログラムの創作的表現とは区別する。"
    },
