    "question": "問15\n ア~エを比較して,特許請求の範囲又は発明の詳細な説明の記載要件に関して,最も不適切と\n考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許請求の範囲は,請求項に区分して,各請求項毎に特許出願人が特許を受けようとする発\n  明を特定するために必要と認める事項のすべてを記載したものであること",
      "イ": "発明の詳細な説明の記載は,その発明の属する技術分野における通常の知識を有する者がそ\n  の実施をすることができる程度に明確かつ十分に記載したものであること",
      "ウ": "特許請求の範囲の記載において,一の請求項に係る発明と他の請求項に係る発明とが同一で\n  ないこと",
      "エ": "特許請求の範囲の記載において,特許を受けようとする発明が明確であること"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "請求項同士が同一の発明を記載することは、記載要件によって一律に禁止されていない。各請求項の明確性やサポート等を満たすかが問題なのでウが不適切。",
    "basis": "特許法36条4項・5項・6項",
    "choiceExplanations": {
      "ア": "請求項ごとに、出願人が発明の特定に必要と認める事項を記載する。",
      "イ": "実施可能要件として、当業者が実施できる程度に明確・十分な説明が必要。",
      "ウ": "他の請求項と必ず異なる発明でなければならないという記載要件はない。",
      "エ": "請求項の発明が明確であることは明確性要件として要求される。"
    },
