    "difficulty": 3,
    "question": "問16\n ア~エを比較して,商標登録出願に係る商標に関して,最も不適切と考えられるものはどれか。\nなお,商標法第3条第2項(使用による特別顕著性)の適用は考えないものとする。",
    "sharedCase": "",
    "choices": {
      "ア": "商標登録出願に係る商標が,日本国内において,政府等以外の者が開設する博覧会の賞と同\n  一の商標に該当する場合には,当該博覧会が特許庁長官により指定されている場合に限り,\n  そのことを理由として商標登録を受けることができない。",
      "イ": "商標登録出願に係る商標が,需要者が何人かの業務に係る商品であることを認識することが\n  できない商標に該当する場合には,そのことを理由として商標登録を受けることができない。",
      "ウ": "商標登録出願に係る商標が,ありふれた氏を普通に用いられる方法で表示する標章のみから\n  なる商標に該当する場合には,そのことを理由として商標登録を受けることができない。",
      "エ": "商標登録出願に係る商標が,商品等の品質等の誤認を生じるおそれがある商標に該当する場\n  合には,そのことを理由として商標登録を受けることができない。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "博覧会の賞に関する不登録事由では、国内の博覧会と外国の非政府博覧会の指定要件を区別する。国内の非政府博覧会にも特許庁長官の指定が必要とするアが不適切。",
    "basis": "商標法3条1項4号・6号、4条1項9号・16号",
    "choiceExplanations": {
      "ア": "国内の非政府博覧会の賞について、特許庁長官の指定が必要という限定はない。指定の条件を別の類型から持ち込んでいる。",
      "イ": "誰の業務の商品か識別できない商標は、識別力がないため原則登録できない。",
      "ウ": "ありふれた氏を普通の方法で表示する標章のみの商標は、原則として登録できない。",
      "エ": "商品の品質等を誤認させるおそれのある商標は不登録事由に該当する。"
    },
