    "officialAnswerNumber": "ウ",
    "explanation": "出版権は複製権又は公衆送信権を有する者が設定できる。登録、存続期間、設定者自身の利用制限を混同しないウが適切。",
    "basis": "著作権法79条・80条・83条・88条",
    "choiceExplanations": {
      "ア": "登録は第三者対抗要件であり、当事者間の出版権設定の効力を生じさせる必須条件ではない。",
      "イ": "設定行為に定めがなければ、最初の出版等から3年が基本。最後の出版のたびに3年が更新されるわけではない。",
      "ウ": "複製権又は公衆送信権の保有者が、その権利に対応する出版権を設定できる。",
      "エ": "出版権者が設定範囲の利用を専有するため、設定者がその範囲を自由に複製できるとはいえない。"
    },
