    "difficulty": 3,
    "question": "問18\n ア~エを比較して,特許権等の権利行使に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "専用実施権者は,特許発明を実施している者に対して,特許権者と共同でなくても,単独で\n  専用実施権の侵害行為の停止を求めることができる。",
      "イ": "特許権者は,特許発明を実施している者に対して,警告をした後でなければ,差止請求権を\n  行使することはできない。",
      "ウ": "特許権者は,侵害者が特許権侵害により,法律上の原因なく利益を得たことにより損害が生\n  じた場合には,侵害者が得たすべての利益の返還を請求することができる。",
      "エ": "特許権者は,特許発明を実施している者に対して,差止請求をしなければ,損害賠償請求権\n  を行使することができない。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "専用実施権者は設定範囲で単独の差止請求ができる。警告、差止め、損害賠償は一律に前後関係が必須ではなく、アが適切。",
    "basis": "特許法100条、民法703条・704条・709条",
    "choiceExplanations": {
      "ア": "専用実施権者は侵害の停止・予防を単独で請求でき、特許権者との共同請求は必須でない。",
      "イ": "事前警告は差止請求の一般的な必須要件ではない。",
      "ウ": "不当利得返還には自己の損失や受益者の善意・悪意等による範囲の問題がある。侵害者の全利益を常に返還させられるとはいえない。",
      "エ": "損害賠償請求に先立って差止請求をする必要はない。それぞれの請求の要件で判断する。"
    },
