    "difficulty": 3,
    "question": "問19\n ア~エを比較して,商標登録出願の拒絶理由通知に対する対応に関して,最も不適切と考えら\nれるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "拒絶理由に係る指定商品等を指定した分割出願を行う。",
      "イ": "出願に係る商標を類似する商標に補正する手続補正書を提出する。",
      "ウ": "拒絶理由に係る指定商品等を削除する手続補正書を提出する。",
      "エ": "審査官の見解に対する反論を記載した意見書を提出する。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "拒絶理由には意見書、指定商品等の削除、分割等で対応する。出願商標を別の類似商標に変更する補正は要旨変更となるためイが不適切。",
    "basis": "商標法10条・16条の2等",
    "choiceExplanations": {
      "ア": "指定商品等を分けて分割出願する対応は可能。分割そのものが拒絶理由を消すとは限らない。",
      "イ": "商標自体を別の類似商標へ差し替えることは、要旨変更として許されない。",
      "ウ": "問題となる指定商品等を削除する補正は、拒絶理由への対応方法になる。",
      "エ": "審査官の判断に反論し、登録可能性を説明する意見書を提出できる。"
    },
