    "question": "問20\n ア~エを比較して,特許協力条約(PCT)に基づく国際出願に関して,最も適切と考えられ\nるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "国際出願をする場合には,日本語で出願をすることができる。",
      "イ": "国際出願後に国際予備審査を請求した後には,請求の範囲についてのみ補正をすることがで\n  きる。",
      "ウ": "国際出願後に国際調査が行われ,国際調査見解書において特許性があるとされた場合には,\n  指定国において方式審査のみが行われ,特許性の審査が行われずに特許権が発生する。",
      "エ": "国際出願をした場合には,その後,権利取得を目的とする指定国において所定の国内移行手\n  続を,優先日から3年以内にする必要がある。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "日本の受理官庁へのPCT国際出願は日本語で行える。国際調査等は各国の特許付与判断そのものではないためアが適切。",
    "basis": "PCT19条・34条、国内移行制度",
    "choiceExplanations": {
      "ア": "日本語による国際出願が可能であり、英語のみの制度ではない。",
      "イ": "国際予備審査での34条補正は、請求の範囲に加えて明細書・図面も対象となる。19条補正と区別する。",
      "ウ": "国際調査見解書は各指定国の審査を拘束せず、各国で特許性審査が行われる。",
      "エ": "国内移行期限は原則優先日から30か月で、国による差もある。3年という一律の期限ではない。"
    },
