    "question": "問21\n ア~エを比較して,著作権に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "共同著作物の著作権については,各共有者は,他の共有者の同意を得なければ,その持分を\n  質権の目的とすることができない。",
      "イ": "著作権の譲渡を第三者に対抗するためには,登録が必要である。",
      "ウ": "著作権者から著作物の利用許諾を得た者は,著作権者の承諾を得なくとも,その著作物を利\n  用する権利を第三者に譲渡することができる。",
      "エ": "著作権は,その全部又は一部を譲渡することができる。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "著作物を利用する権利の譲渡には著作権者の承諾が必要であり、許諾された者が無断で第三者へ移せるとするウが不適切。著作権そのものの譲渡と区別する。",
    "basis": "著作権法61条・63条・65条・77条",
    "choiceExplanations": {
      "ア": "共同著作物の著作権の持分を質入れするには他の共有者の同意が必要。",
      "イ": "著作権譲渡の登録は第三者への対抗要件である。譲渡当事者間の効力の要件とは異なる。",
      "ウ": "利用許諾で得た利用権を第三者へ譲渡するには、原則として著作権者の承諾が必要。",
      "エ": "財産権としての著作権は全部又は一部を譲渡できる。著作者人格権とは異なる。"
    },
