    "difficulty": 3,
    "question": "問22\n ア~エを比較して,特許出願の願書に添付した明細書,特許請求の範囲又は図面の補正に関し\nて,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "最後の拒絶理由通知を受けた場合には,当該拒絶理由通知を受けた時の明細書,特許請求の\n  範囲又は図面に記載した事項の範囲内に限り明細書の補正をすることができる。",
      "イ": "最初の拒絶理由通知を受けた後に特許請求の範囲について補正をする場合には,補正前の特\n  許請求の範囲に記載される事項により特定される発明と,補正後の特許請求の範囲に記載さ\n  れる事項により特定される発明とが,発明の単一性の要件を満たす一群の発明に該当するも\n  のとなるようにしなければならない。",
      "ウ": "補正が認められると,補正をした内容は出願時に遡って効力を生じる。",
      "エ": "最後の拒絶理由通知を受けた場合には,特許請求の範囲に関して請求項の削除や誤記の訂正\n  を目的とした補正をすることができる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "補正の新規事項の判断基準は、拒絶理由通知時の書類ではなく、願書に最初に添付した明細書等である。アは基準時点を誤っている。",
    "basis": "特許法17条の2",
    "choiceExplanations": {
      "ア": "新規事項を追加しない範囲の基礎は出願当初の記載。最後の通知を受けた時の書類を基礎とするのではない。",
      "イ": "最初の通知後の請求項補正では、補正前後の発明の単一性に関する制限を守る必要がある。",
      "ウ": "適法な補正は出願時からその内容で出願されたものとして扱われる。新規事項を後から足せるという意味ではない。",
      "エ": "最後の通知後は目的が限定され、請求項削除や誤記訂正等は認められる目的に含まれる。"
    },
