    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "物品の機能に基づいて形状等が変わる場合、変化前後の形状等を含む動的意匠として出願できる。イが適切。関連意匠は基礎意匠からの展開にも対応する。",
    "basis": "意匠法6条4項・10条",
    "choiceExplanations": {
      "ア": "関連意匠にのみ類似する意匠も、制度の要件を満たせば登録できる。",
      "イ": "その物品の機能に基づく形状・模様・色彩の変化を含めて扱う動的意匠が認められる。",
      "ウ": "図面による出願が可能であり、ひな形・見本の提出が必須ではない。",
      "エ": "関連意匠の出願可能期間は基礎意匠の出願日から10年経過前が基本で、3年ではない。"
    },
