    "choices": {
      "ア": "ベルヌ条約の加盟国では,著作物にcの記号,著作権者名,及び最初の発行年を表示するこ\n  とにより,その表示年に創作があったものと推定される。",
      "イ": "映画の著作物の著作権は,その著作者が映画製作者に対し当該映画の著作物の製作に参加す\n  ることを約束しているときは,当該映画製作者に帰属する。",
      "ウ": "著作権の譲渡契約において,翻訳権,翻案権等が譲渡の目的として特掲されていない場合は,\n  これらの権利は,譲渡した者に留保されたものと推定される。",
      "エ": "映画の著作物の著作権は,その映画の著作物の公表後70年を経過するまでの間,存続する。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "ベルヌ条約は無方式主義を採り、著作権表示で創作年が推定されるという規則はない。アが不適切。著作権表示は注意喚起等の役割を持つ。",
    "basis": "ベルヌ条約5条、著作権法29条・54条・61条2項",
    "choiceExplanations": {
      "ア": "©、権利者名、発行年の表示がベルヌ条約上の創作年の推定を発生させるわけではない。",
      "イ": "参加を約束した著作者の映画の著作権は、法律上の条件のもとで映画製作者に帰属する。",
      "ウ": "27条・28条の権利は譲渡の目的として特掲しなければ譲渡人に留保されたと推定される。",
      "エ": "映画の著作権は原則として公表後70年。期間内に公表されない場合は創作後70年という別の起算規定がある。"
    },
