    "topicTags": [
      "公正取引委員会・知的財産の利用に関する独占禁止法上の指針"
    ],
    "difficulty": 3,
    "question": "問26\n ア~エを比較して,特許ライセンス契約に関して,独占禁止法における不公正な取引方法に該\n当する可能性が低い行為として,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許ライセンス契約において,ライセンスを受けた者が改良発明をした場合に,その権利を\n  ライセンスした者に帰属させること",
      "イ": "特許ライセンス契約において,許諾に係る製品の販売地域を制限すること",
      "ウ": "特許ライセンス契約において,特許権の消滅後にその技術を使用することを制限すること",
      "エ": "特許ライセンス契約終了後に,特許ライセンスを受けた者がライセンスした者の競合品を取\n  り扱うことを禁止すること"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "許諾製品の販売地域の制限は、技術利用の範囲の限定として原則許容される場合がある。改良発明の帰属強制、消滅後の利用制限、終了後の競合品禁止と比較してイの問題可能性が低い。",
    "basis": "公正取引委員会・知的財産の利用に関する独占禁止法上の指針",
    "choiceExplanations": {
      "ア": "改良発明の権利をライセンサーに帰属させる義務は、研究開発意欲を損ない競争を制限するおそれがある。",
      "イ": "販売地域の制限は原則として直ちに不公正な取引方法とはされない。ただし市場の状況等により個別判断される。",
      "ウ": "特許権消滅後まで利用を制限すると、本来自由な技術の利用を妨げるおそれがある。",
      "エ": "終了後の競合品取扱禁止は、合理的な範囲を超えて競争を制限するおそれがある。"
    },
