    "sharedCase": "",
    "choices": {
      "ア": "特許権者以外の者は,特許料を納付することはできない。",
      "イ": "設定登録を受けるための特許料が所定の期間内に納付されない場合,その特許出願は拒絶さ\n  れる。",
      "ウ": "特許出願人の請求により,設定登録を受けるための特許料の特許査定の謄本の送達後の納付\n  期間は,延長される場合がある。",
      "エ": "特許権者は,第4年以後の特許料について,一時に複数年分を納付することができない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "設定登録のための特許料の納付期間には、請求による延長の制度があるのでウが適切。特許料の納付者や複数年分の前納についても区別する。",
    "basis": "特許法18条・108条・110条等",
    "choiceExplanations": {
      "ア": "利害関係人等による納付も可能で、特許権者本人に限られない。",
      "イ": "未納の場合は所定の手続で出願却下の対象となる。発明の特許性を判断する拒絶査定とは区別する。",
      "ウ": "特許査定謄本の送達後の納付期間は、請求により延長される場合がある。",
      "エ": "第4年以後の特許料も複数年分をまとめて納付できる。毎年しか払えないわけではない。"
    },
