    "question": "問28\n ア~エを比較して,著作権に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "私的使用目的で作成された著作物の複製物を,業務での使用目的で頒布することができる。",
      "イ": "他人の著作物に依拠せず自ら独自に創作した著作物が,それより前に創作された他人の著作\n  物と偶然酷似したものである場合,その他人の著作権を侵害する場合がある。",
      "ウ": "公正な慣行に合致し,正当な範囲内で行われるものであれば,公表されていない著作物で\n  あっても引用して利用することができる。",
      "エ": "営利目的ではなく,聴衆又は観衆から料金を受けず,実演家に報酬が支払われない場合であ\n  れば,公表された著作物を著作権者の許諾を得ずに公に上演することができる。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "公表著作物の非営利・無料上演等は、実演家への報酬もないこと等を満たす場合に許諾不要となる。エはその条件を示している。",
    "basis": "著作権法30条・32条・38条・49条",
    "choiceExplanations": {
      "ア": "私的使用の例外で作った複製物を業務用に頒布すると、目的外利用の問題が生じる。",
      "イ": "著作権侵害には依拠が必要。独立創作で偶然似ただけなら、その先行著作物の著作権侵害にはならない。",
      "ウ": "32条の引用の対象は公表された著作物。未公表作品まで同じ規定で自由に引用できない。",
      "エ": "非営利、聴衆等から無料、実演家へ無報酬という条件のもとで公表著作物を上演できる。"
    },
