      "ウ": "IPランドスケープにおいて扱う情報は,特許情報には限定されないが,マーケット情報等\n  のいわゆるビジネス情報は含まれない。",
      "エ": "IPランドスケープには,自社技術の新規用途を見つけるかたちでの新規事業の提案といっ\n  た業務は含まれない。"
