    "difficulty": 3,
    "question": "問32\n ア~エを比較して,特許要件に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許出願に係る発明が,当該特許出願後,当該特許出願が公開される前に日本国内において,\n  公然実施をされた発明と同一の場合には,特許を受けることができない。",
      "イ": "特許出願前にその発明の属する技術の分野における通常の知識を有する者が,公知技術に基\n  づいて容易に発明をすることができたときは,その発明については,特許を受けることがで\n  きない。",
      "ウ": "同一の発明について異なった日に二以上の特許出願があったときは,最先の発明者のみがそ\n  の発明について特許を受けることができる。",
      "エ": "明細書の発明の詳細な説明の記載要件に関しては,特許異議の申立ての理由とすることがで\n  きない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "出願前の公知技術から当業者が容易に発明できた場合、進歩性がないため特許を受けられない。イが適切。新規性・先願の判断の基準も出願時点である。",
    "basis": "特許法29条・39条・113条",
    "choiceExplanations": {
      "ア": "この肢の公然実施は出願後。出願前の公然実施を理由とする新規性欠如と同じではない。",
      "イ": "当業者が出願前の公知技術に基づいて容易に発明できた場合は、進歩性の要件を満たさない。",
      "ウ": "異日出願では原則として最先の出願人が特許を受ける。最先の発明者という基準ではない。",
      "エ": "発明の詳細な説明の実施可能要件違反等は、特許異議申立ての理由になり得る。"
    },
