    "difficulty": 3,
    "question": "問33\n ア~エを比較して,著作権等の侵害又は行使に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "譲渡権者の許諾を得て公衆に譲渡された著作物の原作品又は複製物を公衆に再譲渡する場合,\n  譲渡権の効力は及ばない。",
      "イ": "著作権を侵害している者だけでなく,侵害するおそれがある者に対しても差止請求権を行使\n  することができる。",
      "ウ": "過失により他人の著作権を侵害した者に対しては,刑事罰として拘禁刑又は罰金が科せられ\n  る。",
      "エ": "国内で頒布する目的で,輸入の時において国内で作成したとしたならば著作者人格権の侵害\n  となるべき行為によって作成された物を輸入する行為は,著作者人格権を侵害する行為とみ\n  なされる。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "著作権侵害による刑事責任は故意が基本で、過失だけでこの侵害罪の刑罰が科されるわけではない。民事上の損害賠償と区別してウを選ぶ。",
    "basis": "著作権法26条の2・112条・113条・119条等",
    "choiceExplanations": {
      "ア": "適法に公衆へ譲渡された原作品・複製物の再譲渡には、譲渡権の消尽が認められる。",
      "イ": "差止めは現に行う侵害の停止だけでなく、侵害のおそれに対する予防も含む。",
      "ウ": "過失による侵害でも民事責任は問題となるが、著作権侵害罪の故意の要件とは異なる。",
      "エ": "国内での頒布目的で、国内作成なら人格権侵害となる物を輸入する行為は、みなし侵害の対象となる。"
    },
