    "difficulty": 3,
    "question": "問34\n ア~エを比較して,関税法における模倣品の水際取締りに関して,最も適切と考えられるもの\nはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "育成者権を侵害する物品は,輸入してはならない貨物の対象とはならない。",
      "イ": "他人の商品の形態を模倣した商品は,輸入してはならない貨物の対象とはならない。",
      "ウ": "税関長は,輸入されようとする貨物が,知的財産侵害物品に該当すると認定した場合,裁判\n  所の判決によらず,その貨物を没収して廃棄することができる。",
      "エ": "特許権者は,認定手続がとられたときは,税関長に対し,特許庁長官の意見を聴くことを求\n  めることができる。この求めがあった場合,税関長は,政令で定めるところにより特許庁長\n  官に対し意見を求めなければならない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "知的財産侵害貨物と認定された貨物について、税関長には没収・廃棄等の権限があり、裁判所の判決を必須としない。ウが適切。",
    "basis": "関税法69条の11以下",
    "choiceExplanations": {
      "ア": "育成者権を侵害する物品も輸入禁止貨物の対象に含まれる。",
      "イ": "不正競争防止法の形態模倣に該当する貨物も水際取締りの対象となり得る。",
      "ウ": "税関での認定手続を経て、税関長が貨物を没収・廃棄できる。民事裁判の判決を待つ制度ではない。",
      "エ": "特許庁長官への意見照会は所定の要件・手続による。求めがあれば常に税関長が照会しなければならないという無条件の義務ではない。"
    },
