    "difficulty": 3,
    "question": "問35\n ア~エを比較して,契約に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許権譲渡契約において,譲受人が譲渡対価を支払うまでは,譲渡人である特許権者は,譲\n  渡対価の支払の履行期限にかかわらず譲渡に係る債務の履行を拒むことができる。",
      "イ": "契約関係にある当事者間において相手方の行為により損害を被ったとしても,契約書に規定\n  のない事項による場合は,損害賠償請求をすることができない。",
      "ウ": "契約の内容につき債務不履行があったとしても,相手方はこれを理由に解除できない場合が\n  ある。",
      "エ": "売買契約の目的物として特定した物が買主の納品先に運送中に天災により双方当事者の責任\n  なく滅失した場合,買主は代金の支払を拒むことができない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "債務不履行があっても軽微な不履行等では解除できない場合がある。ウが適切。支払期限や危険負担など契約の具体的な条件を確認する。",
    "basis": "民法415条・533条・536条・541条等",
    "choiceExplanations": {
      "ア": "同時履行の抗弁では相手方債務の履行期も問題となる。支払期限に関係なく常に拒めるわけではない。",
      "イ": "契約書に明記がなくても、債務不履行や不法行為等の要件を満たせば損害賠償を請求できる。",
      "ウ": "契約・取引上軽微な不履行など、解除が認められない場合がある。",
      "エ": "引渡し前に双方無責で滅失した場合、危険負担の規律により買主が反対給付を拒める場合がある。"
    },
