    "question": "問36\n ア~エを比較して,特許無効審判に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許無効審判は,複数の者により共同して請求される場合がある。",
      "イ": "特許無効審判は,特許権の消滅後においても,請求される場合がある。",
      "ウ": "特許無効審判は,利害関係人以外により請求される場合はない。",
      "エ": "特許無効審判の審決に対する訴えは,東京地方裁判所に提起する。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "特許無効審判の審決取消訴訟は東京高等裁判所の専属管轄で、知的財産高等裁判所が扱う。東京地方裁判所へ提起するとするエが不適切。",
    "basis": "特許法123条・132条・178条",
    "choiceExplanations": {
      "ア": "複数の利害関係人等が共同で無効審判を請求することがある。",
      "イ": "過去の侵害等を巡る利害が残るため、特許権消滅後にも無効審判の請求が可能。",
      "ウ": "基準日時点の無効審判は利害関係人が請求する制度であり、理由によって請求人がさらに限定される場合がある。",
      "エ": "審決取消訴訟の管轄は東京高等裁判所であり、地方裁判所ではない。"
    },
