    "difficulty": 3,
    "question": "問37\n ア~エを比較して,著作権,著作物に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "素材が著作物である編集著作物を複製する場合,素材である著作物と編集著作物の著作権者\n  全員から許諾を得ることが必要になる場合がある。",
      "イ": "著作権の享有には,いかなる方式の履行をも要しない。",
      "ウ": "ベルヌ条約には,内国民待遇の原則が規定されている。",
      "エ": "日本国民の著作物であっても,ベルヌ条約未加盟国において最初に発行された著作物は,日\n  本の著作権法の保護対象とはならない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "日本国民の著作物は、日本の著作権法の保護対象である。最初の発行がベルヌ条約非加盟国だったことだけで保護から外れず、エが不適切。",
    "basis": "著作権法6条・12条・17条、ベルヌ条約5条",
    "choiceExplanations": {
      "ア": "編集著作物の権利は素材の権利を消さない。利用内容により両方の権利者の許諾が必要となる。",
      "イ": "著作権の享有に登録等の方式は不要である。",
      "ウ": "ベルヌ条約は内国民待遇を原則としている。",
      "エ": "日本国民の著作物は発行国にかかわらず保護対象。外国人の著作物についての条約・発行地の条件と混同しない。"
    },
