      "イ": "弁理士は知的財産権に関する訴訟で補佐人として業務を行える。",
      "ウ": "登録料等の納付手続には非弁理士による業務の禁止の例外があり、納付手続まで一律に独占業務とはいえない。",
      "エ": "付記弁理士であっても、特定侵害訴訟の代理は弁護士との共同受任が必要である。"
