    "question": "1 化学品メーカーX社の技術者甲は,新しい素材に関する発明Aと,当該素材の使用方法に関\n する発明Bについて,特許出願をしようと考え,X社の知的財産部の部員乙に相談した。甲の\n 質問に対し,乙が発言1をしている。\n甲   「今回の発明Aと発明Bは,それぞれ別の発明と考えられますが,1つの願書で特許出\n     願をすることはできますか。」\n発言1 「発明Aと発明Bが発明の単一性の要件を満たす関係にある場合には,複数の発明で\n     あっても1つの願書で特許出願をすることができます。」\n その後,発明Aについて2025年3月に特許出願Pをし,出願審査の請求をしたところ,2026年3月に最初の拒絶理由通知を受けた。これに対し,意見書及び手続補正書を提出した結\n果,2026年7月に最後の拒絶理由通知を受けた。特許出願Pの明細書には発明Bについて記\n載されていた。甲の質問に対し,乙が発言2をしている。\n甲   「宣伝効果や他社への牽制効果を考えて,特許出願Pを実用新案登録出願に変更したい\n     と思いますが,その際に発明Bを実用新案登録請求の範囲に記載することはできます\n     か。」\n発言2 「特許出願Pを実用新案登録出願に変更することは可能ですが,方法の考案は実用新案\n     法の保護対象でないために登録を受けることはできません。」\n 以上を前提として,問1~問4に答えなさい。\n\n問2\n 【理由群I】の中から,問1において適切又は不適切と判断した理由として,最も適切と考え\nられるものを1つ選びなさい。\n【理由群I】",
    "sharedCase": "1 化学品メーカーX社の技術者甲は,新しい素材に関する発明Aと,当該素材の使用方法に関\n する発明Bについて,特許出願をしようと考え,X社の知的財産部の部員乙に相談した。甲の\n 質問に対し,乙が発言1をしている。\n甲   「今回の発明Aと発明Bは,それぞれ別の発明と考えられますが,1つの願書で特許出\n     願をすることはできますか。」\n発言1 「発明Aと発明Bが発明の単一性の要件を満たす関係にある場合には,複数の発明で\n     あっても1つの願書で特許出願をすることができます。」\n その後,発明Aについて2025年3月に特許出願Pをし,出願審査の請求をしたところ,2026年3月に最初の拒絶理由通知を受けた。これに対し,意見書及び手続補正書を提出した結\n果,2026年7月に最後の拒絶理由通知を受けた。特許出願Pの明細書には発明Bについて記\n載されていた。甲の質問に対し,乙が発言2をしている。\n甲   「宣伝効果や他社への牽制効果を考えて,特許出願Pを実用新案登録出願に変更したい\n     と思いますが,その際に発明Bを実用新案登録請求の範囲に記載することはできます\n     か。」\n発言2 「特許出願Pを実用新案登録出願に変更することは可能ですが,方法の考案は実用新案\n     法の保護対象でないために登録を受けることはできません。」\n 以上を前提として,問1~問4に答えなさい。",
