    "sharedCase": "2 食料品メーカーX社は,新規の「マーガリン」及び「チョコレートスプレッド」の商品を開\n 発し,これらの商品名として,マーケティング部から「ABC」が提案された。X社の知的財\n 産部の部員甲は,これらの新商品について商標登録出願を検討し,その結果について,知的財\n 産部の部長乙に対して,発言1~2をしている。なお,商品区分として,「マーガリン」は第\n 29類,「チョコレートスプレッド」は第30類に属する。\n発言1 「商品である『マーガリン』と,『チョコレートスプレッド』とは異なる商品区分です。\n     したがって,これらの商品を一の商標登録出願に指定商品として指定することはでき\n     ないので,指定商品『マーガリン』と,指定商品『チョコレートスプレッド』として,\n     別々に商標登録出願をする必要があります。」\n発言2 「商標登録を受けようとする商標として,特殊なフォントで記載した『ABC』の文字\n     について商標登録出願をした後であっても,願書に標準文字の欄を追加し,『ABC』\n     の文字のフォントを通常のフォントに補正することができます。」\n 以上を前提として,問5~問8に答えなさい。",
    "caseNumber": 2,
