    "question": "3 テレビ局X社の法務部の部員甲が,発言1~2をしている。\n発言1 「X社が制作し放送したアニメ作品Aが,ネットユーザー乙によって,動画投稿サイト\n     に,誰の許諾も得ずに投稿されています。アニメ作品Aには,映像制作会社Y社が制\n     作した劇場用映画の映像が,Y社の許諾の下に1分ほど部分使用されています。乙の\n     行為は,Y社が有する権利を侵害しています。」\n発言2 「X社が動画サイトにアップロードしたドキュメント番組Bを,ネットユーザー丙が,\n     個人的に視聴する目的で録音及び録画をしました。このドキュメント番組Bには,レ\n     コード製作者W社が発行したCDの音楽がタイトル画面のテーマ曲として用いられて\n     います。丙の行為は,W社が有する権利を侵害しています。」\n 以上を前提として,問9~問12に答えなさい。\n\n問10\n 【理由群V】の中から,問9において適切又は不適切と判断した理由として,最も適切と考え\nられるものを1つ選びなさい。\n【理由群V】",
    "sharedCase": "3 テレビ局X社の法務部の部員甲が,発言1~2をしている。\n発言1 「X社が制作し放送したアニメ作品Aが,ネットユーザー乙によって,動画投稿サイト\n     に,誰の許諾も得ずに投稿されています。アニメ作品Aには,映像制作会社Y社が制\n     作した劇場用映画の映像が,Y社の許諾の下に1分ほど部分使用されています。乙の\n     行為は,Y社が有する権利を侵害しています。」\n発言2 「X社が動画サイトにアップロードしたドキュメント番組Bを,ネットユーザー丙が,\n     個人的に視聴する目的で録音及び録画をしました。このドキュメント番組Bには,レ\n     コード製作者W社が発行したCDの音楽がタイトル画面のテーマ曲として用いられて\n     います。丙の行為は,W社が有する権利を侵害しています。」\n 以上を前提として,問9~問12に答えなさい。",
    "caseNumber": 3,
    "choices": {
      "ア": "引用となるため",
      "イ": "公衆送信権の侵害となるため",
      "ウ": "頒布権が消尽したため",
      "エ": "上映権の侵害となるため"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "動画サイトへの無断投稿の中心となる侵害は公衆送信権。Y社映像の短さだけで引用が成立するわけではないのでイ。",
    "basis": "著作権法23条・32条",
    "choiceExplanations": {
      "ア": "番組をそのまま無断投稿する行為は、適法な引用の条件を満たすものとされていない。",
      "イ": "サイトから視聴可能にする投稿は、公衆送信・送信可能化に関わる権利を侵害する。",
      "ウ": "原作品等の流通に関する頒布権の消尽から、ネット送信の自由は導けない。",
      "エ": "動画投稿で問われるのは送信行為であり、観客へスクリーン等で公に映す上映とは異なる。"
    },
