    "sharedCase": "3 テレビ局X社の法務部の部員甲が,発言1~2をしている。\n発言1 「X社が制作し放送したアニメ作品Aが,ネットユーザー乙によって,動画投稿サイト\n     に,誰の許諾も得ずに投稿されています。アニメ作品Aには,映像制作会社Y社が制\n     作した劇場用映画の映像が,Y社の許諾の下に1分ほど部分使用されています。乙の\n     行為は,Y社が有する権利を侵害しています。」\n発言2 「X社が動画サイトにアップロードしたドキュメント番組Bを,ネットユーザー丙が,\n     個人的に視聴する目的で録音及び録画をしました。このドキュメント番組Bには,レ\n     コード製作者W社が発行したCDの音楽がタイトル画面のテーマ曲として用いられて\n     います。丙の行為は,W社が有する権利を侵害しています。」\n 以上を前提として,問9~問12に答えなさい。",
