    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問13\n 生活用品メーカーX社は,ハンカチを指定商品とした商標Aについて商標登録出願Mを行った。\n当該出願後に先行出願調査を行ったところ,タオルメーカーY社がタオルを指定商品とする商標\nAに類似する商標Bについて,商標登録出願Mと同じ日に商標登録出願Nをしていたことが判明\nした。ア~エを比較して,X社の考えとして,最も不適切と考えられるものを1つ選びなさい。\n但し,タオルとハンカチは類似する商品であるとする。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "特許庁長官からY社と協議するように命令されることがある。",
      "イ": "わが社とY社のどちらが商標登録を受けられるか,くじで決めることがある。",
      "ウ": "Y社から承諾さえ得れば,わが社は商標登録出願Mについて商標登録を受けることができる。",
      "エ": "出願公開後であってもY社が商標登録出願Nを取り下げれば,商標登録出願Mについて,商\n  標登録を受けることができる。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "同日出願の類似商標・類似商品については、協議による一方の決定や不調時のくじ等の制度がある。他方の承諾だけで当然に登録できるとするウが不適切。",
    "basis": "商標法8条等",
    "choiceExplanations": {
      "ア": "同日出願の場合、特許庁長官が期間を指定して協議を命ずることがある。",
      "イ": "協議が成立しない場合等には、公正な方法によるくじで一方を決めることがある。",
      "ウ": "同日出願の調整や他の登録要件が必要で、単なる承諾だけで登録が保証されない。",
      "エ": "他方の出願が取り下げられれば、この同日競合の問題が解消され得る。公開済みだから取り下げが無意味にはならない。"
    },
