    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "著作権法61条2項・63条・77条"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問15\n X社は,イラストレーター甲に,X社のパンフレットに掲載するイラストAの制作を依頼し,\n完成した際に報酬を甲に支払うことを約束した。X社の法務部の部員乙は,甲と著作権譲渡契約\n又は著作物利用許諾契約を締結し,X社がなるべく制約を受けずに,イラストAを広い範囲で利\n用できるようにしたいと考えている。ア~エを比較して,乙の考えとして,最も適切と考えられ\nるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "著作物利用許諾契約を締結する場合,利用期間や利用方法について決めることはできない。",
      "イ": "著作物利用許諾契約を締結する場合,イラストAに係る著作物について,X社へ利用許諾し\n  たことを登録しなければ,利用許諾の効力は発生しない。",
      "ウ": "著作権譲渡契約を締結する場合,イラストAに係る著作権を甲からX社へ移転したことを登\n  録しなければ,移転の効力は発生しない。",
      "エ": "著作権譲渡契約において,「甲は,イラストAに生ずるすべての著作権を何らの制約なくX\n  社に譲渡する」と規定しておくことが考えられるが,この規定だと,イラストAの翻案権等\n  及び翻案等した著作物の利用権は甲に留保されたものと推定される。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "すべての著作権を譲渡するとだけ書いても、27条・28条の権利が特掲されないと甲への留保が推定される。エが適切。広い利用を望むなら翻案等の権利も明示する。",
    "basis": "著作権法61条2項・63条・77条",
    "choiceExplanations": {
      "ア": "許諾の利用期間・利用方法は契約で定められる。",
      "イ": "許諾契約の効力は登録を条件として生じるものではない。",
      "ウ": "著作権移転の登録は第三者対抗要件であり、当事者間の移転の成立要件ではない。",
      "エ": "翻案権等と二次的著作物利用権を特掲しなければ、譲渡人への留保が推定される。人格権は別途扱う。"
    },
