    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問16\n 陶磁器メーカーX社は,マグカップAを新たに販売しようとしている。ア~エを比較して,X\n社の知的財産部の部員の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "マグカップAは,その一部である取っ手の形状が特徴的なので,当該取っ手について意匠登\n  録出願をすることとした。",
      "イ": "同時に販売する予定の複数のマグカップは,各マグカップの模様に統一感はないが,マグ\n  カップとしては同一物品であるので,これら複数のマグカップを組物の意匠として意匠登録\n  出願をすることとした。",
      "ウ": "マグカップAには,ハワイを意識したデザインコンセプトが採用されており,当該デザイン\n  コンセプトを砂糖壺に採用し,マグカップAを本意匠,当該砂糖壺を関連意匠として,意匠\n  登録出願をすることとした。",
      "エ": "マグカップAは,側面に施された模様が特徴的で,当該模様は,他の種類の陶磁器にも用い\n  ることができるので,当該模様そのものについて意匠登録出願をすることとした。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "マグカップの特徴的な取っ手は部分意匠として保護を求められる。アが適切。意匠は抽象的なデザインコンセプトや模様だけの保護ではない。",
    "basis": "意匠法2条・8条・10条",
    "choiceExplanations": {
      "ア": "物品の一部である取っ手を部分意匠として出願する方法がある。",
      "イ": "組物には全体としての統一性等が必要。同一物品であることだけでは足りない。",
      "ウ": "同じコンセプトでも、本意匠との意匠の類似が必要。マグカップと砂糖壺という異なる用途等を無視できない。",
      "エ": "模様は物品等と結び付いた意匠として保護される。抽象的な模様そのものを物品から切り離して登録する制度ではない。"
    },
