    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "特許法17条の2・44条・121条・136条等"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問17\n ソフトウェア企業X社は,クラウド上で動作する暗号鍵管理システムの発明について特許出願\nPを行った。しかし,特許出願Pは審査を経て拒絶査定の謄本が送達され,X社の知的財産部の\n部員が今後とり得る手段を検討している。ア~エを比較して,部員の考えとして,最も適切と考\nえられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "審決取消訴訟を提起し,拒絶査定を取り消してもらえば,登録を受けることができる。",
      "イ": "拒絶査定の謄本送達日から30日以内に限り,拒絶理由のない請求項のみについて分割出願\n  をすることができる。",
      "ウ": "拒絶査定不服審判を請求し,あわせて,拒絶理由がある請求項1を削除し,拒絶理由のない\n  請求項2を残す補正書を審判請求と同時に提出する。",
      "エ": "拒絶査定不服審判を請求すると,当該審判では,審査官とは異なる審判官3人又は5人の合\n  議体で審理され,拒絶査定における拒絶の理由は審理されない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "拒絶査定に対して不服審判を請求し、その請求と同時に請求項削除の補正をする方法がある。ウが適切。査定と審決を区別する。",
    "basis": "特許法17条の2・44条・121条・136条等",
    "choiceExplanations": {
      "ア": "拒絶査定を直ちに審決取消訴訟で争うのではなく、まず不服審判の手続を利用する。",
      "イ": "拒絶査定後の分割可能期間を30日に限定するのは誤り。原則3か月等の法定時期がある。",
      "ウ": "不服審判請求と同時に、拒絶理由のある請求項を削除する補正が可能。補正内容・目的の要件を守る。",
      "エ": "審判でも査定の拒絶理由は審理の対象。審判官の合議体になったから従前の理由が消えるわけではない。"
    },
