    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問20\n 食品メーカーX社が新製品の即席麺の販売を開始したところ,競合会社であるY社からX社に,\nY社の有する特許権Pを侵害する旨の警告書が送られてきた。ア~エを比較して,X社の考えと\nして,最も適切と考えられるものを1つ選びなさい。",
