    "choices": {
      "ア": "特許権Pに対する特許異議の申立ては,利害関係人に限られる。今回警告書が届いたことで\n  利害関係が生じたため,わが社が特許異議の申立てを行うことができる。",
      "イ": "他のメーカーにも同じような警告書が送られているようであり,他社と共同で特許権Pに対\n  して特許無効審判を請求することができる。",
      "ウ": "特許権Pに対して特許無効審判を請求する前に,特許侵害訴訟が提起された場合には,特許\n  無効審判を請求することはできない。",
      "エ": "特許権Pの存続期間が1年後に満了する場合には,特許権Pに対する特許無効審判の請求期\n  限は今後1年以内に限定される。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "共通の特許で警告された他社と、無効審判を共同請求することは可能。イが適切。侵害訴訟や権利消滅は当然の請求禁止理由ではない。",
    "basis": "特許法113条・123条・132条",
    "choiceExplanations": {
      "ア": "特許異議申立ては所定期間内なら何人もでき、警告で利害関係を得ることは必要条件ではない。",
      "イ": "複数の利害関係人が共同で無効審判を請求できる。",
      "ウ": "侵害訴訟が先に提起されても無効審判請求はできる。訴訟中の無効の抗弁とも区別する。",
      "エ": "権利消滅後も無効審判請求は可能で、存続期間満了までの1年に限定されない。"
    },
