    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問21\n 化学品メーカーX社は,新規な洗浄剤Aに係る特許出願Pをし,その後,洗浄剤Aを改良した\n洗浄剤Bについて,特許出願Pに基づいて国内優先権の主張を伴う特許出願Qをした。特許出願\nQの特許請求の範囲には,洗浄剤Aに係る発明と,洗浄剤Bに係る発明と,洗浄剤A及び洗浄剤\nBの両方の上位概念である洗浄剤Cに係る発明が記載され,明細書には洗浄剤A及び洗浄剤Bが\n記載されていた。特許出願Qが登録された後,Y社が洗浄剤Bと同一の洗浄剤Dの製造販売を開\n始したので,X社は,Y社に対する権利行使を検討している。ア~エを比較して,X社の考えと\nして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "洗浄剤Bに係る特許権に基づいてY社に権利行使をする場合には,特許出願Pに係る優先権\n  証明書を予めY社に提示して警告する必要がある。",
      "イ": "洗浄剤Dの製造販売に対する差止請求をするにあたっては,洗浄剤Bに係る特許権と,洗浄\n  剤Cに係る特許権のいずれの特許権に基づいて権利行使をしてもよい。",
      "ウ": "特許出願Qの明細書には,洗浄剤A及び洗浄剤Bに係る発明しか記載されていないため,洗\n  浄剤Cに係る特許権の効力は,洗浄剤Dの製造販売行為に及ばない。",
      "エ": "特許出願Pは,その出願日から1年4カ月経過後に取り下げられたものとみなされるため,\n  取り下げられたものとみなされた後は,洗浄剤Aに係る特許権の効力は,洗浄剤Dの製造販\n  売行為に及ばない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "DはBと同一であり、Bを含む上位概念Cの技術的範囲にも入る。登録されたB又はCの請求項に基づく権利行使が可能なのでイが適切。",
    "basis": "特許法41条・42条・70条・100条",
    "choiceExplanations": {
      "ア": "登録特許の差止請求に優先権証明書の事前提示・警告が一般的な必須要件ではない。",
      "イ": "DがB及びその上位概念Cの技術的範囲に属するなら、どちらの登録請求項にも基づける。",
      "ウ": "権利範囲は特許請求の範囲に基づく。明細書が実施例A・BだけだからCの請求項がDに及ばないとはいえない。",
      "エ": "先のPの取下げ擬制は後のQの登録権利を消すものではない。先の出願の手続状態と後の権利の効力を混同している。"
    },
