    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問22\n 自動車メーカーX社は,自動車に係る形状等Aについての意匠権を有している。ア~エを比較\nして,X社の知的財産部の部員の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "形状等Aに含まれるヘッドライトと同一の形状等Bであるヘッドライトに,当該意匠権の効\n  力が及ぶ。",
      "イ": "形状等Aとは非類似の形状等であるが,X社と出所の混同を生ずるおそれがある自動車に,\n  当該意匠権の効力が及ぶ。",
      "ウ": "形状等Aと類似する形状等Cである自動車の玩具に,当該意匠権の効力が及ぶことはない。",
      "エ": "形状等Aと類似する形状等Dである自動車が描かれたTシャツに,当該意匠権の効力が及ぶ。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "物品の用途・機能等の類似も意匠類否で問題になる。自動車とその玩具は物品が非類似で、自動車の意匠権が玩具へ及ぶことはないのでウが適切。",
    "basis": "意匠法23条・24条",
    "choiceExplanations": {
      "ア": "自動車全体の登録意匠から、その一部のヘッドライトだけを独立して保護できるとは限らない。",
      "イ": "意匠が非類似なら、出所混同だけで意匠権侵害とはならない。他の法の保護とは別。",
      "ウ": "自動車と玩具は用途・機能が異なる物品で、形態の共通だけでは類似意匠にならない。",
      "エ": "自動車の意匠とその絵を載せたTシャツは物品等が異なり、同じ図形を描いたことだけではこの意匠権は及ばない。"
    },
