    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問23\n カメラメーカーX社は,新型オートフォーカス機構に係る発明Aについて,特許出願を予定し\nている。X社の知的財産部の部員が発明Aの出願書類案について検討している。ア~エを比較し\nて,部員の考えとして,最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "発明Aのポイントであるレンズ駆動アルゴリズムの具体的なステップは,競合に知られたく\n  ないので,明細書を読んだだけでは当業者が実施できないように,図面や数値条件を省略す\n  べきである。",
      "イ": "特許請求の範囲の「高速にレンズを移動させる」という記載は,「高速」の基準が曖昧で不\n  明確なので,例えば客観的数値などで限定するよう修正すべきである。",
      "ウ": "願書に要約書が添付されていないので,発明の概要を400字以内で記載した要約書を作成\n  し願書に添付する必要がある。",
      "エ": "特許請求の範囲に記載のオートフォーカス機構は,明細書に記載されていないので,明細書\n  に記載を追加して特許請求の範囲の記載内容と整合させるべきである。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "当業者が実施できないように重要な手順等を隠すと実施可能要件を満たさない。特許は必要な技術を開示して保護を得る制度なのでアが不適切。",
    "basis": "特許法36条・特許法施行規則",
    "choiceExplanations": {
      "ア": "実施に必要な手順等を意図的に省略してはいけない。秘密にしたいなら出願との戦略選択を検討する。",
      "イ": "曖昧な高速という表現を客観的な条件等へ修正するのは明確性を高める対応。",
      "ウ": "要約書を添付し、所定の400字以内で発明概要を記載する必要がある。",
      "エ": "出願前の案の段階で請求項と明細書を整合させ、サポート要件等を満たす記載を用意する。"
    },
