    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問25\n 素材メーカーX社の技術者甲は,商品開発部において新規な製品Aの開発業務に従事していた。\n甲は,人事異動により営業部所属となったが,営業部において製品Aに関する発明Pを完成した。\nその後甲はX社を退職したが,X社は製品Aの製造販売の開始を決定した。ア~エを比較して,\nX社の知的財産部の部員乙の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "甲の職務発明として認められる部分は,発明Pのうち,甲が商品開発部から営業部に異動し\n  た時点で保有していたアイデアまでとなる。",
      "イ": "甲が営業部において会社の設備などの経営資源を使わずに発明Pを完成していたとしたら,\n  発明Pは職務発明とはいえない。",
      "ウ": "甲は営業部に異動となる前に商品開発部で発明Pに関連する製品Aの開発業務に従事してい\n  たので,発明Pは職務発明である。",
      "エ": "甲は営業部において発明Pを完成したが,所属していた営業部では営業職であったので,製\n  品Aの販売活動が甲の職務の範囲に含まれていたとしても,発明Pは職務発明とはいえない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "職務発明には従業者の現在だけでなく過去の職務も関係する。商品開発部での開発業務に属する発明Pを在職中に完成したのでウが適切。",
    "basis": "特許法35条",
    "choiceExplanations": {
      "ア": "職務発明を異動時の未完成アイデアだけに切り分けるものではない。完成した発明と職務の関係で判断する。",
      "イ": "会社設備を使ったかどうかだけが職務発明の要件ではない。業務範囲と現在・過去の職務との関係が重要。",
      "ウ": "異動前の商品開発の職務も考慮されるため、本件の発明Pは職務発明となる。",
      "エ": "営業職という職名だけで否定できず、過去の開発業務等を含めて判断する。"
    },
