    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問27\n 家具メーカーX社は,形状が特徴的であるソファーAを開発して,国内のみにおいて意匠権D\nを取得し,ソファーAを販売したところ人気商品になった。X社は最近になって,外国でソ\nファーAと色は異なるが形状が類似したソファーBが販売されており,日本のY社がソファーB\nを国内に輸入しようとしているという情報を入手した。X社の知的財産部では,ソファーBを入\n手し検討したところ,Y社のソファーBを輸入する行為が意匠権Dを侵害するおそれがあるとの\n結論になった。ア~エを比較して,X社の考えとして,最も適切と考えられるものを1つ選びな\nさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "意匠権Dの侵害が国内で発生していない段階でも,侵害のおそれがあるソファーBが国内に\n  輸入される見込みがあれば,輸入差止めの申立てができるので早急に対応するのが望ましい。",
      "イ": "X社が輸入を差し止めるための認定手続をとるよう申立てを行うと,ソファーBを輸入する\n  者には,当該手続がとられることは通知されるが,権利者保護の観点から,意匠権者の氏名\n  等は通知されない。",
      "ウ": "税関長は,認定手続を経た後でなければ,輸入されようとするソファーBを没収して廃棄す\n  るように命じることはできないが,認定手続が開始された後であればいつでも,ソファーB\n  を輸入しようとする者にその積戻しを命ずることができる。",
      "エ": "X社は,意匠権Dを侵害するおそれがあるソファーBの輸入に対し,特許庁長官に証拠を提\n  出し,輸入を差し止めるための認定手続をとるよう申し立てることができる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "国内侵害がまだ起きていなくても、侵害物品の輸入を予防するため税関へ輸入差止申立てができる。アが適切。日本の意匠権は日本への輸入に対応する。",
    "basis": "関税法69条の11以下",
    "choiceExplanations": {
      "ア": "輸入見込みの段階で差止申立てに対応でき、国内で売られるまで待つ必要はない。",
      "イ": "認定手続では輸入者に権利者の氏名等の所定情報も通知される。匿名で行う制度ではない。",
      "ウ": "認定手続開始だけで直ちに、いつでも積戻しを命令できるわけではない。侵害該当性の認定等の段階を区別する。",
      "エ": "差止申立ての提出先は税関長であり、特許庁長官ではない。"
    },
