    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問28\n レストラン運営会社X社は,新たに店名をAとするイタリアンレストランを開業した。X社で\nは,Aを商標として,レストランにおける飲食物の提供を指定役務とした商標登録出願を行った\nところ,登録査定の謄本が送達された。ア~エを比較して,X社の総務部の部員の考えとして,\n最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "登録料は,商標権の存続期間の10年分を一括で支払うことも,前半5年と後半5年に分割\n  して納付することもできる。",
      "イ": "登録料を登録査定の謄本の送達があった日から30日以内に納付できない場合,商標権の設\n  定登録が行われる場合はない。",
      "ウ": "商標権の存続期間は,何回でも更新することができる。",
      "エ": "商標権の存続期間の満了前6カ月から満了の日までに更新登録の申請をしなくても,その後\n  に更新手続を行うことができる。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "設定登録料は通常30日以内に納付するが、納付期間延長等の制度がある。30日を過ぎると設定登録が絶対にないというイが不適切。",
    "basis": "商標法19条・20条・41条の2・43条等",
    "choiceExplanations": {
      "ア": "10年分の一括納付又は前後半の5年分ずつの分割納付ができる。",
      "イ": "所定の期間延長等が認められる場合があり、30日という通常期限だけで一律に登録不能とはいえない。",
      "ウ": "商標は更新回数の上限なく、条件を満たせば更新できる。",
      "エ": "通常の更新申請期間後も所定期間内の更新・回復等が可能な場合がある。無期限に可能という意味ではない。"
    },
