    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問29\n 種苗メーカーX社は,技術者甲が育成した品種Aについて品種登録出願手続を行うこととした。\nア~エを比較して,X社の考えとして,最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "品種登録出願の審査において拒絶理由が発見された場合,出願者に通知され,意見書の提出\n  の機会が与えられる。",
      "イ": "品種登録出願をしたときは,当該出願について品種登録がされるまで,その内容に関して出\n  願公表されることはない。",
      "ウ": "品種登録出願の願書は,農林水産大臣に対して提出しなければならない。",
      "エ": "品種Aは永年性植物に関するものであり,育成者権の存続期間は,品種登録の日から30年\n  となる。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "品種登録には登録前の出願公表がある。登録まで内容が全く公表されないとするイが不適切。",
    "basis": "種苗法5条・13条・17条・19条等",
    "choiceExplanations": {
      "ア": "拒絶理由があれば出願者へ通知され、意見書提出の機会が与えられる。",
      "イ": "出願公表の制度があり、品種登録前にも所定事項が公表される。",
      "ウ": "願書の提出先は農林水産大臣。特許庁への特許出願とは異なる。",
      "エ": "永年性植物の育成者権は登録日から30年。原則25年のその他の品種と区別する。"
    },
