    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問31\n 俳優甲は,自分のブログに様々な写真画像を掲載している。ア~エを比較して,甲の考えとし\nて,最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "写真画像Aは,甲が,高校の同窓会で,同窓会に参加したメンバーと撮影したものである。\n  同窓会に参加したメンバーに同意を得ずに写真画像Aをブログに掲載すると,メンバーの肖\n  像権が問題となる場合がある。",
      "イ": "写真画像Bは,甲が,人気俳優乙が飼っている猫を撮影したものである。乙に同意を得ずに\n  写真画像Bをブログに掲載すると,乙のパブリシティ権が問題となる場合がある。",
      "ウ": "写真画像Cは,甲が,ドラマのロケ地の風景を撮影したもので,当該ロケ地で開催される祭\n  りのポスターの一部が小さく写ってしまった。ポスターの著作権者の許諾を得ずに写真画像\n  Cをブログに掲載しても,当該著作権者の公衆送信権の侵害とならない場合がある。",
      "エ": "写真画像Dは,甲の友人丙が,甲のプライベートを撮影したものである。丙の許諾を得ずに\n  写真画像Dをブログに掲載すると,丙の公衆送信権の侵害となる場合がある。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "パブリシティ権は人の氏名・肖像等の顧客吸引力に関する人格的利益。飼い猫という物の写真に、飼い主の権利が当然及ぶとするイが不適切。",
    "basis": "肖像・パブリシティの人格的利益、著作権法23条・30条の2",
    "choiceExplanations": {
      "ア": "撮影時の同意とネット公開の同意は同じではない。他の参加者の肖像・プライバシーが問題になり得る。",
      "イ": "物や動物自体の顧客吸引力を、飼い主の人格権としてのパブリシティ権で当然保護することはできない。",
      "ウ": "小さく付随的に写ったポスターは、付随対象著作物の利用の条件を満たせば許諾不要となる場合がある。",
      "エ": "写真の著作権者は撮影者丙となり得る。甲が被写体だから無断投稿できるわけではない。"
    },
