    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問32\n X社は,商標「ABC」,指定商品「スムージー」について商標権Mを有している。X社は,\nY社が経営しているジュースバー「ABC」で提供されているスムージーについて,パッケージ\nに「ABC」の文字を記載して販売されていることを発見したため,Y社に対する商標権Mに基\nづく差止請求権の行使について検討している。ア~エを比較して,X社の考えとして,最も適切\nと考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "X社は,Y社に対して商標権Mを侵害する旨の警告書を送付したところ,Y社は,パッケー\n  ジの「ABC」の文字の書体をゴシック体に変更して,販売を再開した。この場合,X社は\n  Y社に対して差止請求を行うことはできない。",
      "イ": "X社が調査をしたところ,ジュースバー「ABC」は,現時点では周知ではないが,Y社は,\n  商標権Mに係る商標登録出願前から使用していることが判明した。この場合,Y社は先使用\n  権を主張するため,X社が差止請求をしても裁判で認められる可能性は低い。",
      "ウ": "X社が,Y社に対して商標権Mを侵害している旨の警告書を送付したところ,Y社は「ス\n  ムージー」への商標「ABC」の使用を中止したが,「ABC」の文字が記載されたパッ\n  ケージの廃棄はしていない。この場合,X社はY社に対して差止請求を行うことができる。",
      "エ": "X社が調査をしたところ,商標権Mは3カ月前に存続期間が満了し,更新登録の申請も行わ\n  れていないことが判明した。この場合,X社がY社に対して差止請求を行うことができる可\n  能性はない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "使用中止後も侵害表示付き包装が残り、再侵害のおそれ等があれば停止・予防や廃棄を請求できる。ウが適切。",
    "basis": "商標法32条・36条・更新制度",
    "choiceExplanations": {
      "ア": "書体を変えただけで必ず非類似になるわけではなく、類似商標の使用なら差止めの対象になり得る。",
      "イ": "商標の先使用権には出願時の周知性等が必要。単に以前から使っていたことだけでは足りない。",
      "ウ": "侵害の予防のため、残存する包装の廃棄等を含む差止請求が認められ得る。",
      "エ": "満了から3か月なら所定の更新手続等が可能な期間内の場合があり、差止可能性を完全には否定できない。"
    },
