    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問33\n 化粧品メーカーX社では,競合Y社の特許権に対する対応を検討している。ア~エを比較して,\nX社の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "X社が昨年から販売している化粧品AはY社の特許権の権利範囲に含まれるが,X社は,当\n  該特許権の出願後,設定登録前に,化粧品Aを販売していたので,当該特許権が存在しても\n  X社は化粧品Aの販売を継続できる。",
      "イ": "新規事業に関して,特許調査により障害となり得るY社の特許権を発見した場合であっても,\n  当該新規事業を開始していない段階では,X社は利害関係人に該当しないので,特許無効審\n  判を請求することはできない。",
      "ウ": "化粧品BのY社の特許権の権利範囲への属否の検討において,構成要素が異なり,その異な\n  る構成要素が特許発明の本質的な部分でない場合には,Y社の特許権の侵害とされることは\n  ない。",
      "エ": "Y社は原料に係る特許権を有し,X社がY社から購入した当該原料を使った化粧品を製造販\n  売する場合,当該原料に係る特許権についてY社から実施許諾を受ける必要はない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "権利者Y社から適法に購入した原料については、原則として特許権が消尽し、その原料の使用に再許諾は不要。エが適切。",
    "basis": "特許法79条・123条、均等論・特許権の消尽",
    "choiceExplanations": {
      "ア": "先使用権の基準は出願時の実施・準備。出願後、登録前に売り始めただけでは先使用権は成立しない。",
      "イ": "具体的な新規事業で障害となる特許なら、事業開始前でも利害関係人となることがある。",
      "ウ": "相違部分が本質的でない等の条件を満たす場合、均等侵害となり得る。構成の差だけで侵害を否定できない。",
      "エ": "権利者が適法に販売したその原料について、使用のために同じ特許の許諾を改めて受ける必要は原則ない。"
    },
