    "difficulty": 3,
    "question": "6 玩具メーカーX社は,2026年1月に新たな知育玩具Aを完成させたので,知育玩具Aに\n ついて2026年3月に日本で特許出願Pを行った。その後,X社は,知育玩具Aについて2026年5月に販売を開始した。X社の技術者甲と知的財産担当の乙は,知育玩具Aについて\n の外国での特許権取得のための手続について次の会話を行った。問35~問37に答えなさい。\n甲 「知育玩具Aについての外国での特許権取得に関係する条約にはどのようなものがあります\n   か。」\n乙 「パリ条約,特許協力条約(PCT), 1 ,特許法条約(PLT)等があります。」\n甲 「PCTに基づく国際出願を行った場合,各指定国に対する国内移行手続はいつまでに行う\n   必要がありますか。」\n乙 「特許出願Pに基づく優先権を主張して国際出願を行った場合,各指定国に対する国内移行\n   手続は,原則として, 2 から 3 以内に行う必要があります。」\n【語群VII】\n\n問35\n 【語群VII】の中から空欄 1 に入る語句として最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "6 玩具メーカーX社は,2026年1月に新たな知育玩具Aを完成させたので,知育玩具Aに\n ついて2026年3月に日本で特許出願Pを行った。その後,X社は,知育玩具Aについて2026年5月に販売を開始した。X社の技術者甲と知的財産担当の乙は,知育玩具Aについて\n の外国での特許権取得のための手続について次の会話を行った。問35~問37に答えなさい。\n甲 「知育玩具Aについての外国での特許権取得に関係する条約にはどのようなものがあります\n   か。」\n乙 「パリ条約,特許協力条約(PCT), 1 ,特許法条約(PLT)等があります。」\n甲 「PCTに基づく国際出願を行った場合,各指定国に対する国内移行手続はいつまでに行う\n   必要がありますか。」\n乙 「特許出願Pに基づく優先権を主張して国際出願を行った場合,各指定国に対する国内移行\n   手続は,原則として, 2 から 3 以内に行う必要があります。」\n【語群VII】",
