    "sharedCase": "7 出版社であるX社が企画中の本について,編集部の部員甲と法務部の部員乙が以下の会話を\n している。問38~問40に答えなさい。\n甲 「知的財産法の解説本Aを企画しています。全体をわが社の従業者が編集しますが,技術や\n   コンテンツ,デザインなど知的財産に関する異なるテーマ毎に10個の章立てをして,章\n   毎に外部の専門家の先生に執筆を依頼する予定です。」\n乙 「素材の選択又は配列によって創作性を有するものであれば,解説本Aは 1 になると考\n   えられます。」\n甲 「解説本Aの帯には権威付けのため,コンテンツ業界で有名な音楽家やデザイナーに推薦者\n   として名前を提供してもらう予定です。」\n乙 「有名な方が権威を与えるために名前を提供したのであれば 2 と考えられます。」\n甲 「解説本Aを外国語に翻訳して海外での出版も検討していますが,著作物を保護するための\n   条約にはどのようなものがありますか。」\n乙 「著作物の保護については『内国民待遇』や『無方式主義』の原則などを定めた 3 があ\n   ります。」\n【語群VIII】",
