    "difficulty": 3,
    "question": "問1\n ア~エを比較して,特許戦略に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許出願人は,出願公開後にその特許出願に係る発明を実施している者に対して,特許出願\n  に係る公開特許公報を提示して警告をし,特許権の設定登録後に補償金の支払を請求するこ\n  とができる。",
      "イ": "新規な発明について,特許出願をせずに,営業秘密として管理して不正競争防止法による保\n  護を受ける場合は,別途,経済産業省において,不正競争防止法上の営業秘密に該当するか\n  否かの審査を受ける必要がある。",
      "ウ": "特許出願人は,特許庁に対して追加の手数料を支払うことで早期審査制度や優先審査制度を\n  利用することができる。",
      "エ": "特許権者が特許発明を実施していない場合に,当該特許発明について実施許諾の申出があれ\n  ば,特段の事情がない限り通常実施権を許諾しなくてはならない。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "出願公開後の実施者へ公開公報等で警告し、特許権の設定登録後に補償金を請求できる。営業秘密の保護や審査の迅速化を登録・追加料金と混同しない。",
    "basis": "特許法65条・83条等、早期審査制度",
    "choiceExplanations": {
      "ア": "公開後の警告等の条件を満たす実施について、設定登録後に補償金を請求できる。登録前から行使できる特許権とは別。",
      "イ": "営業秘密は秘密管理性・有用性・非公知性で判断され、経済産業省による事前の認定審査は不要。",
      "ウ": "早期審査や優先審査は所定の要件・事情説明等による。追加手数料を払えば使える制度ではない。",
      "エ": "不実施というだけで許諾申出を承諾する一般義務はない。不実施による裁定には別途要件・手続がある。"
    },
