      "ア": "私的使用の目的であっても,著作権者の許諾を得ずに,コピープロテクションを外して複製\n  を行うことはできない。",
      "イ": "美術の著作物の原作品を,著作権者の許諾を得ずに,街路やビルの外壁など一般公衆の見や\n  すい屋外の場所に恒常的に設置することはできない。",
      "ウ": "公表された映画の著作物については,著作権者の許諾を得ずに引用して利用することはでき\n  ない。",
