    "difficulty": 3,
    "question": "問4\n ア~エを比較して,特許係争の対応に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "請求不成立の審決を受けた特許無効審判の請求人は,審決謄本の送達のあった日から60日\n  以内に,東京高等裁判所に審決取消訴訟を提起することができる。",
      "イ": "特許権侵害に対する損害賠償が請求された場合,侵害者が故意又は過失により侵害行為をし\n  たことを,権利者が立証することを待って反論する。",
      "ウ": "特許無効審判により特許が無効になった場合であっても,当該特許に対応する米国の特許は\n  同時に無効とはならない。",
      "エ": "特許権の全範囲に専用実施権が設定されている場合には,特許権者が提起した差止請求訴訟\n  の請求が認容される場合はない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "各国の特許は独立している。日本の特許が無効になっても対応する米国特許が自動的に無効となるわけではなく、ウが適切。",
    "basis": "特許法100条・103条・178条、パリ条約4条の2",
    "choiceExplanations": {
      "ア": "審決取消訴訟の出訴期間は原則審決謄本送達から30日。60日という一般期限ではない。",
      "イ": "特許侵害では過失が推定される。権利者が過失を立証するまで待つだけでは不十分。",
      "ウ": "対応出願であっても特許は各国で独立し、日本の無効審決は米国特許を自動的に消滅させない。",
      "エ": "専用実施権の設定後も特許権者の差止請求権が当然に失われるわけではない。"
    },
    "explanationCoverage": "full",
