    "difficulty": 3,
    "question": "問5\n ア~エを比較して,商標登録出願に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "同一又は類似の商標について2以上の出願があった場合に,後に商標登録出願した者であっ\n  ても商標登録を受けられる場合がある。",
      "イ": "商標登録出願に係る指定商品が,他人の商標登録に係る指定商品と非類似の場合には,当該\n  他人の商標の存在を理由に,当該商標登録出願が拒絶される場合はない。",
      "ウ": "商標登録出願に係る商標が,商品の品質や役務の質の誤認を生ずるおそれがある場合には,\n  当該商標登録出願は拒絶される。",
      "エ": "対比される商標から生ずる称呼が同一であっても,外観,観念,取引の実情を総合的に考慮\n  した結果,互いに非類似の商標と判断される場合がある。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "商品・役務が非類似でも、著名商標との混同等を理由に拒絶される場合がある。イの一律否定が不適切。",
    "basis": "商標法4条・8条、商標類否判断",
    "choiceExplanations": {
      "ア": "商標の類否だけでなく商品・役務、先願の状態等によるため、後願でも登録可能な場合がある。",
      "イ": "非類似の商品・役務でも出所の混同のおそれ等があれば拒絶理由になり得る。",
      "ウ": "品質や役務の質を誤認させるおそれは不登録事由。",
      "エ": "称呼だけでなく外観・観念・取引実情を総合して判断する。同じ読み方でも非類似のことがある。"
    },
