    "sharedCase": "",
    "choices": {
      "ア": "国の機関が英語に翻訳した知的財産高等裁判所の判決",
      "イ": "学術的な性質を有する模型",
      "ウ": "データベース",
      "エ": "無言劇"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "裁判所の判決と、国の機関等が作成したその翻訳物等は、著作者の権利の目的とならない。アが適切。",
    "basis": "著作権法10条・12条の2・13条",
    "choiceExplanations": {
      "ア": "判決の国の機関による翻訳は13条により権利の目的から除かれる。私人の独自解説とは異なる。",
      "イ": "学術的な模型は創作性等を満たせば著作物に含まれる。",
      "ウ": "情報の選択又は体系的な構成に創作性を有するデータベースは保護される。",
      "エ": "無言劇も創作的な表現として著作物になり得る。"
    },
