    "sharedCase": "",
    "choices": {
      "ア": "登録意匠と類似するか否かの判断は,創作者の視覚を通じて起こさせる美感に基づいて行う。",
      "イ": "意匠権の存続期間は,意匠登録出願の日から25年で終了する。",
      "ウ": "登録意匠の範囲は,願書の記載及び願書に添付した図面に記載され又は願書に添付した写真,\n  ひな形若しくは見本により現わされた意匠に基づいて判断される。",
      "エ": "出願当初の願書の記載や図面などの要旨を変更する補正があったものと意匠権の設定の登録\n  があった後に認められたときは,その意匠登録出願は,その補正について手続補正書を提出\n  した時にしたものとみなされる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "意匠の類似は需要者の視覚を通じた美感に基づいて判断する。創作者の視覚を基準にするアが不適切。",
    "basis": "意匠法20条・24条・27条",
    "choiceExplanations": {
      "ア": "判断主体は需要者。創作者が似ていると感じるかという主観で決めない。",
      "イ": "現行制度の意匠権の存続期間は出願日から25年。旧出願には経過措置がある。",
      "ウ": "願書及び添付図面等が登録意匠の範囲を判断する基礎となる。",
      "エ": "登録後に要旨変更補正だったと認められた場合、補正書提出時を出願時とみなす規定がある。"
    },
