    "sharedCase": "",
    "choices": {
      "ア": "明細書や図面に,特許請求の範囲に記載されていない発明を記載することができる。",
      "イ": "特許庁長官は,明細書の一部の記載が欠けていることを発見した場合,出願人に対して,欠\n  落部分を補完することができる旨を通知する。",
      "ウ": "明細書には,何人も特許出願に係る発明を実施できるように,発明を明確かつ十分に記載す\n  ることが必要である。",
      "エ": "明細書には,特許請求の範囲の記載だけで発明を技術的に理解できる場合であっても,その\n  発明を記載しなければならない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "実施可能要件は『何人も』ではなく、その技術分野の通常の知識を有する者が実施できる程度を要求する。ウが不適切。",
    "basis": "特許法36条4項・38条の4等",
    "choiceExplanations": {
      "ア": "明細書等には請求項にしていない発明も記載できる。記載しただけで権利範囲になるわけではない。",
      "イ": "明細書等に欠落がある場合、補完可能である旨を通知する制度がある。補完には出願日への影響等の条件がある。",
      "ウ": "技術の専門知識がない人まで実施できる必要はない。当業者の知識を前提に判断する。",
      "エ": "請求項の記載だけで理解できても、明細書の記載自体を省略してよいわけではない。"
    },
