    "examDate": "2026-03-08",
    "qNumber": 10,
    "type": "multiple-choice",
    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "不正競争防止法2条1項1号・19条"
    ],
    "difficulty": 3,
    "question": "問10\n ア~エを比較して,不正競争防止法第2条第1項第1号(周知表示混同惹起行為)に関して,\n最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "本号に該当する行為をした場合には,それが普通名称を普通に用いられる方法で使用した場\n  合であっても,差止や損害賠償請求の対象となる。",
      "イ": "本号で保護される商品等表示は,周知である必要があるため,一地域だけではなく,全国的\n  に広く知られていることが必要である。",
      "ウ": "本号で保護される商品等表示は,単に出願していなかった商標や,権利期間が満了してし\n  まった意匠であっても,保護の対象となる場合がある。",
      "エ": "本号における他人の商品等との混同は,商品等の出所が同一である場合を指しており,いわ\n  ゆる親子会社関係のような関係を誤認させる場合は含まれない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "周知表示の保護は登録商標や存続中の意匠権に限定されない。未登録表示や権利消滅後の形態も要件を満たせば保護され、ウが適切。",
    "basis": "不正競争防止法2条1項1号・19条",
    "choiceExplanations": {
      "ア": "普通名称を通常の方法で使う行為等には適用除外がある。",
      "イ": "周知性は一定の地域・取引者等で認められることがあり、全国的周知が必須ではない。",
      "ウ": "登録の有無とは別に、周知な商品等表示で混同等の要件を満たすかを判断する。",
      "エ": "混同には同一主体と誤認する場合だけでなく、親子会社等の関係があるとの誤認も含まれる。"
    },
