    "difficulty": 3,
    "question": "問11\n ア~エを比較して,特許法における発明者に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "企業等における技術者,研究者は,発明者として技術的思想の創作行為に現実に寄与したこ\n  とを立証できるよう,実験ノート等を用いて日頃から証拠を残しておくことが望ましい。",
      "イ": "複数人が共同で発明したときには,当該発明が職務発明である場合を除き,特許を受ける権\n  利は発明者全員が共同で有する。",
      "ウ": "公開特許公報に発明者として記載されている者は,常に特許を受ける権利を有する。",
      "エ": "部下である発明者に対して一般的な助言をしただけの管理者である上司は,実質的に発明を\n  完成したといえず,発明者として認められない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "公報の発明者欄は創作した人物を示し、特許を受ける権利の現在の保有者を保証するものではない。承継等を無視するウが不適切。",
    "basis": "特許法29条・33条・35条等",
    "choiceExplanations": {
      "ア": "実験ノート等は技術的思想の創作への具体的寄与を示す証拠として有用。",
      "イ": "共同発明では原則発明者が権利を共同保有し、職務発明の原始帰属等は別途判断する。",
      "ウ": "権利は譲渡等され得る。発明者として記載されていても権利を常に保有するとは限らない。",
      "エ": "一般的な助言や管理だけでは、発明の具体的な創作への実質的寄与がないため発明者に当たらない。"
    },
