    "difficulty": 3,
    "question": "問12\n ア~エを比較して,独占禁止法に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "会社の役員が他社の役員を兼任することについて,独占禁止法違反となる場合がある。",
      "イ": "特許ライセンス契約において,ライセンスに係る製品の販売価格を制限することは,独占禁\n  止法上,問題にならない。",
      "ウ": "特許ライセンス契約において,ライセンスを受けた者が競争技術を開発することを禁止する\n  ことは,独占禁止法上,問題にならない。",
      "エ": "1つの会社が,品質の優れた商品を安く供給することにより市場を独占してしまう場合は,\n  私的独占として独占禁止法違反となる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "役員兼任により一定の取引分野の競争を実質的に制限する場合等には、独占禁止法の問題が生じる。アが適切。",
    "basis": "独占禁止法13条、知的財産の利用に関する独占禁止法上の指針",
    "choiceExplanations": {
      "ア": "役員兼任も競争への影響等によって禁止の対象となる場合がある。",
      "イ": "販売価格の制限は競争を制限するおそれがあり、特許ライセンスというだけで問題がなくなるわけではない。",
      "ウ": "競争技術の開発を禁じることは研究開発競争を妨げるおそれがある。",
      "エ": "優れた商品を安価に提供した結果の高い市場シェアだけでは私的独占にならない。排除・支配行為等の要件で判断する。"
    },
