    "question": "問13\n ア~エを比較して,特許協力条約(PCT)に係る国際出願に関して,最も適切と考えられる\nものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "国際出願をしていずれかの指定国で特許権が発生した場合には,国際出願で指定した他の指\n  定国において自動的に特許権が発生する。",
      "イ": "出願人は,国際出願に対する国際調査報告を受領した後に,国際事務局に補正書を提出する\n  ことにより,1回に限り請求の範囲について補正をすることができる。",
      "ウ": "国際出願が優先権の主張を伴う場合であっても,国際出願日から18カ月経過後に国際公開\n  される。",
      "エ": "出願人は,国際出願に対する国際予備審査報告を受領した後であっても,国際事務局に補正\n  書を提出することができる。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "国際調査報告の受領後、19条により国際事務局へ請求の範囲の補正を1回提出できる。イが適切。",
    "basis": "PCT19条・21条・34条等",
    "choiceExplanations": {
      "ア": "各指定国の特許は独立に審査・付与され、一国の登録で他国に自動発生しない。",
      "イ": "19条補正は国際調査報告後に国際事務局へ行う請求の範囲の1回の補正。",
      "ウ": "優先権主張があれば国際公開は原則優先日から18か月を基準にする。国際出願日からとは限らない。",
      "エ": "国際予備審査終了後に国際事務局へ補正すれば足りる制度ではない。審査中の34条補正や国内段階の補正と区別する。"
    },
