    "choices": {
      "ア": "商品化権とは,著作権の支分権の一種であり,商品化権を侵害された場合,著作権法上,商\n  品化権の侵害を理由に差止請求をすることができるものである。",
      "イ": "差止請求権とは,著作権の支分権の一種であり,著作権等を侵害する者又は侵害するおそれ\n  がある者に対して,侵害の停止又は予防を請求することができる権利である。",
      "ウ": "口述権とは,著作権の支分権の一種であり,無断で著作物を公に口述されない権利であり,\n  言語の著作物について認められるものである。",
      "エ": "出版権とは,著作権の支分権の一種であり,出版社に対して複製権を許諾する場合に自動的\n  に設定されるものである。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "言語の著作物を公に口述することを専有する口述権は、著作権の支分権。ウが適切。差止請求権や出版権は同じ分類ではない。",
    "basis": "著作権法24条・79条・112条",
    "choiceExplanations": {
      "ア": "商品化権は契約実務上の概念であり、その名称の独立した法定支分権があるわけではない。",
      "イ": "差止請求権は侵害に対する救済の権利。複製権等の利用を専有する支分権とは区別する。",
      "ウ": "口述権は言語の著作物を公に口述する行為を対象とする支分権である。",
      "エ": "出版権は設定により生じる権利。単なる複製許諾だけで自動設定されず、著作権の支分権でもない。"
    },
