    "difficulty": 3,
    "question": "問16\n ア~エを比較して,特許法に規定する国内優先権制度に関して,最も適切と考えられるものは\nどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "複数の特許出願に基づいて国内優先権を主張することはできない。",
      "イ": "国内優先権の主張を伴う特許出願は,その特許出願の日から遅滞なく出願公開される。",
      "ウ": "国内優先権の主張を伴う特許出願については,その特許出願の日から3年以内に出願審査の\n  請求をすることができる。",
      "エ": "実用新案登録出願に基づいて国内優先権の主張を伴う特許出願をすることはできない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "国内優先権を伴う後の出願でも、審査請求の原則期限はその後の出願日から3年。ウが適切。公開の起算と区別する。",
    "basis": "特許法41条・48条の3・64条",
    "choiceExplanations": {
      "ア": "要件を満たす複数の先の出願に基づく国内優先権主張も可能。",
      "イ": "後の出願をした直後に必ず公開されるわけではなく、原則先の出願日から1年6か月が基準。",
      "ウ": "後の出願の出願日から3年以内に審査請求できる。",
      "エ": "実用新案登録出願を先の出願とする国内優先権も、所定の条件を満たせば主張可能。"
    },
    "explanationCoverage": "full",
