    "difficulty": 3,
    "question": "問17\n ア~エを比較して,映画の著作物に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "映画の著作物には,映画の効果に類似する視覚的又は視聴覚的効果を生じさせる方法で表現\n  され,かつ,物に固定されている著作物が含まれる。",
      "イ": "映画の著作物の著作権は,その著作者が映画製作者に対し当該映画の著作物の製作に参加す\n  ることを約束しているときは,当該映画製作者に帰属する。",
      "ウ": "映画の著作物の著作権は,その創作後70年以内に公表されないときは,その創作後70年\n  を経過するまでの間,存続する。",
      "エ": "実演家の許諾を得て映画の著作物において録音・録画された実演については,これをさらに\n  録音・録画する場合にもその実演家の許諾が必要である。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "実演家が映画への録音・録画を許諾した場合、原則としてその映画を再利用するたびに再度録音・録画の許諾は不要となる。いわゆるワンチャンス主義に反するエが不適切。",
    "basis": "著作権法2条3項・29条・54条・91条2項",
    "choiceExplanations": {
      "ア": "固定された映像で映画と類似の視覚・視聴覚効果を生じるものも映画の著作物に含まれる。",
      "イ": "製作参加を約束する等の条件を満たす場合、映画の著作権は映画製作者に帰属する。",
      "ウ": "創作後70年以内に公表されない映画は、創作後70年を基準に存続期間を計算する。",
      "エ": "許諾済みの映画の実演の再録音・録画には原則再許諾不要。ただし録音物への別の録音など、法律の例外には注意する。"
    },
