    "difficulty": 3,
    "question": "問18\n ア~エを比較して,特許権の侵害に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許権を取得した場合であっても,その特許発明が先願に係る他人の特許発明の利用発明に\n  該当する場合には,当該利用発明に係る製品を製造する行為は,その他人の特許権の侵害に\n  該当する。",
      "イ": "特許権者に無断で,その特許発明に係る製品を事業で使用した場合であっても,当該製品が\n  当該特許発明の特許出願の時から日本国内にあった場合には,特許権の侵害に該当しない。",
      "ウ": "特許権者に無断で,その特許発明に係る製品を試験販売する行為は,特許権の侵害に該当し\n  ない。",
      "エ": "特許権者に無断で,その特許発明に係る製品を製造した場合であっても,その特許権の特許\n  出願に係る発明の内容を知らないで自らその発明をし,特許出願の際,現に日本国内におい\n  てその発明の実施である事業をしているときは,当該製品の製造が,その実施をしている発\n  明及び事業の目的の範囲内であれば,特許権の侵害に該当しない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "試験又は研究のための実施の例外と、市場での試験販売は異なる。試験販売だから一律に非侵害とするウが不適切。",
    "basis": "特許法69条・72条・79条",
    "choiceExplanations": {
      "ア": "自分の特許があっても先願の他人の特許を利用するなら、その権利を無視して製造できない。",
      "イ": "特許出願時から日本国内にある物には、その特許権の効力が及ばない旨の規定がある。",
      "ウ": "試験販売は商業的な譲渡等であり、試験・研究の例外に当然には入らない。",
      "エ": "出願内容を知らない独立発明の実施について、出願時の国内事業等の条件を満たせば先使用権で保護される。"
    },
