    "question": "問19\n ア~エを比較して,商標権の更新登録の申請に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "更新登録の申請は,商標権の存続期間満了前6カ月から満了の日までに行わなければならな\n  い。",
      "イ": "更新期間経過後であっても,経済産業省令で定める期間内であれば割増登録料を納付して更\n  新手続を行うことができる場合がある。",
      "ウ": "更新登録の申請は,商標権者のみが行うことができる。",
      "エ": "更新登録の申請の際に,登録商標を使用していない場合は,更新登録は認められない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "更新申請には使用の証明が一般的な条件とされていない。不使用取消審判の制度とは別なので、エが不適切。",
    "basis": "商標法19条・20条・43条等",
    "choiceExplanations": {
      "ア": "通常の更新申請期間は存続期間満了前6か月から満了日まで。",
      "イ": "通常期間後も所定の期間内には割増登録料を伴う更新手続等が可能な場合がある。",
      "ウ": "更新申請の主体は商標権者。通常・専用使用権者というだけでは申請できない。",
      "エ": "未使用だから更新申請が当然に認められないわけではない。不使用による取消しは別の手続で判断される。"
    },
