    "question": "問20\n ア~エを比較して,登録後の無効審判等に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "登録実用新案が新規性を有していない場合,実用新案登録は,無効理由を有する。",
      "イ": "特許無効審判は,利害関係人でなければ請求することができない。",
      "ウ": "特許権の消滅後であっても,特許無効審判を請求することができる。",
      "エ": "複数の者が共同で特許無効審判を請求することはできない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "無効審判は複数の者が共同して請求できる。共同請求を否定するエが不適切。実用新案も登録後に実体要件の欠如が問題となる。",
    "basis": "実用新案法37条、特許法123条・132条",
    "choiceExplanations": {
      "ア": "実用新案は無審査で登録されても、新規性を欠けば無効理由となる。",
      "イ": "特許無効審判は利害関係人の請求を基本とする。理由による請求人の限定にも注意する。",
      "ウ": "特許権の消滅後にも無効審判を請求することができる。",
      "エ": "法律は共同の審判請求を認めており、複数の者であることは請求を妨げない。"
    },
