    "question": "問21\n ア~エを比較して,特許出願に対する拒絶理由の通知への対応に関して,最も不適切と考えら\nれるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許出願人は,最後の拒絶理由の通知を受けた場合に,請求項を削除する補正をすることが\n  できる。",
      "イ": "特許出願人は,最初の拒絶理由の通知を受けた場合に,特許出願を分割することができる。",
      "ウ": "特許出願人は,最初の拒絶理由の通知を受けた場合に,特許出願を意匠登録出願に変更する\n  ことができる。",
      "エ": "特許出願人は,最初の拒絶理由の通知を受けた場合に,願書に最初に添付した明細書又は図\n  面に記載されていない事項を特許請求の範囲に追加する補正をすることができる。"
    },
