    "question": "問22\n ア~エを比較して,著作隣接権の存続期間の満了に関して,最も不適切と考えられるものはど\nれか。",
    "sharedCase": "",
    "choices": {
      "ア": "有線放送に関しては,その有線放送が行われた日の属する年の翌年から起算して50年を経\n  過した時",
      "イ": "実演に関しては,その実演が行われた日の属する年の翌年から起算して70年を経過した時",
      "ウ": "放送に関しては,その放送が行われた日の属する年の翌年から起算して50年を経過した時",
      "エ": "レコードに関しては,そのレコードの発行がされた日の属する年の翌年から起算して50年\n  を経過した時"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "実演・レコードは原則70年、放送・有線放送は50年という区別がある。レコードを50年とするエが不適切。",
    "basis": "著作権法101条",
    "choiceExplanations": {
      "ア": "有線放送の隣接権は行われた年の翌年から50年が基本。",
      "イ": "実演の隣接権は行われた年の翌年から70年が基本。",
      "ウ": "放送の隣接権は行われた年の翌年から50年が基本。",
      "エ": "レコードは所定の発行等を起算として原則70年。発行されなかった場合等には別の起算規定がある。"
    },
    "explanationCoverage": "full",
