    "difficulty": 3,
    "question": "問23\n ア~エを比較して,契約に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "契約にはない事項について相手方から損害を受けた場合,不法行為に基づいて相手方に損害\n  賠償請求をすることができる場合がある。",
      "イ": "債務の全部の履行が不能である場合も,相当の期間を定めて履行の催告をしなければ,契約\n  を解除することはできない。",
      "ウ": "民法の任意規定に違反する契約は,契約当事者の合意があったとしても有効な契約とは認め\n  られない。",
      "エ": "契約は,契約書を作成して署名押印がなければ有効な契約と認められない。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "契約書に規定がない事項でも、不法行為の要件を満たせば損害賠償請求が可能。アが適切。契約の成立や解除を常に書面・催告に結び付けない。",
    "basis": "民法91条・522条・542条・709条",
    "choiceExplanations": {
      "ア": "契約責任とは別に、不法行為に基づく賠償請求が成立する場合がある。",
      "イ": "全部の履行不能等では、催告なしの解除が認められる。",
      "ウ": "任意規定は当事者の合意で異なる定めをすることができる。強行規定と区別する。",
      "エ": "原則として意思表示の合致で成立し、契約書・署名押印は常に成立要件ではない。"
    },
