    "difficulty": 3,
    "question": "問24\n ア~エを比較して,特許権の効力に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許発明が物を生産する方法の発明である場合,当該方法により生産した物を譲渡する行為\n  には特許権の効力は及ばない。",
      "イ": "特許発明が方法の発明である場合,当該方法の使用にのみ用いる物の輸入には特許権の効力\n  が及ぶ。",
      "ウ": "特許発明が物の発明である場合,当該物の譲渡の申出をする行為には特許権の効力は及ばな\n  い。",
      "エ": "特許発明がプログラムの発明である場合,電気通信回線を通じて,当該プログラムを提供す\n  る行為には特許権の効力は及ばない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "方法の使用にのみ用いる物の業としての輸入は間接侵害の対象。イが適切。実施の定義は製造・使用だけでなく譲渡等にも及ぶ。",
    "basis": "特許法2条3項・68条・101条",
    "choiceExplanations": {
      "ア": "物を生産する方法の発明では、その方法で生産した物の譲渡等も実施に含まれる。",
      "イ": "その方法の使用にのみ用いる物を業として輸入する行為は、間接侵害として扱われる。",
      "ウ": "物の発明の譲渡等の申出も実施に含まれる。販売前だから常に対象外ではない。",
      "エ": "プログラム等を電気通信回線で提供する行為も譲渡等に含まれ、効力の対象となり得る。"
    },
