    "question": "問25\n ア~エを比較して,知的財産権に関する国際条約に関して,最も不適切と考えられるものはど\nれか。",
    "sharedCase": "",
    "choices": {
      "ア": "TRIPS協定は,加盟国が他国の国民に与える有利な利益,特典,特権又は免除は,即時\n  かつ無条件に他のすべての加盟国の国民にも与えなければならない,という「最恵国待遇」\n  について定めている。",
      "イ": "TRIPS協定は,WTO(世界貿易機関)の紛争解決手段を利用することができない。",
      "ウ": "マドリッド協定議定書は,複数の国において商標登録を受けるための手続を簡素化する。",
      "エ": "ハーグ協定は,意匠の国際登録に関する取決めである。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "TRIPS協定の紛争にはWTOの紛争解決制度を利用できる。利用できないとするイが不適切。",
    "basis": "TRIPS協定4条・64条、マドリッド・ハーグの制度",
    "choiceExplanations": {
      "ア": "最恵国待遇は原則として他国へ与えた利益を他の加盟国の国民にも即時・無条件に与える。協定上の例外はある。",
      "イ": "TRIPSはWTO協定の一部であり、WTOの紛争解決手続が適用される。",
      "ウ": "マドリッド制度は商標の複数国での保護に向けた手続を簡素化する。",
      "エ": "ハーグ制度は意匠の国際登録に関する制度。特許や商標の制度ではない。"
    },
