    "question": "問27\n ア~エを比較して,特許出願人による意見書の提出に関して,最も不適切と考えられるものは\nどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許出願人は,拒絶査定を受けた場合であっても,意見書を提出することができる。",
      "イ": "特許出願人は,最後の拒絶理由の通知を受けた場合であっても,意見書を提出することがで\n  きる。",
      "ウ": "特許出願人は,意見書と共に実験結果の成績証明書を提出することができる。",
      "エ": "特許出願人が意見書の提出期間内に意見書を提出せずに手続補正書のみを提出した場合で\n  あっても,審査官が再度,拒絶理由を通知する場合がある。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "拒絶査定を受けた後の不服対応は拒絶査定不服審判等による。通常の拒絶理由通知への意見書を出すだけで審査に反論する段階ではないためアが不適切。",
    "basis": "特許法50条・121条、拒絶理由対応手続",
    "choiceExplanations": {
      "ア": "拒絶理由通知と拒絶査定を区別する。査定後は所定の不服審判の請求等が必要となる。",
      "イ": "最後の拒絶理由通知でも指定期間内に意見書を提出し反論できる。",
      "ウ": "主張を裏付ける実験成績証明書等を意見書と併せて提出できる。新規事項の追加とは別問題。",
      "エ": "補正内容を審査した結果、別の拒絶理由等を再度通知する場合がある。意見書がないだけで再通知が不可能にはならない。"
    },
