    "difficulty": 3,
    "question": "問28\n ア~エを比較して,商標権の侵害に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "商標権者が,故意により自己の商標権を侵害した者に対し,その侵害により自己が受けた損\n  害の賠償を請求する場合において,その者がその侵害の行為を組成した商品を譲渡したとき\n  は,譲渡数量に商標権者がその侵害の行為がなければ販売することができた商品の単位数量\n  あたりの利益の額を乗じて得た額を,商標権者が受けた損害の額とすることができる。",
      "イ": "他人の商標権を故意に侵害した者であっても,刑事罰が科される場合はない。",
      "ウ": "商標権者が,故意により自己の商標権を侵害した者に対し,その侵害により自己が受けた損\n  害の賠償を請求する場合において,その登録商標の使用に対し受けるべき金銭の額に相当す\n  る額を超える額を,商標権者は請求することができない。",
      "エ": "商標権者は,自己の商標権を侵害するおそれがある者に対し,その商標登録の内容を記載し\n  た書面を提示して警告した後でなければ,その侵害の停止又は予防を請求することができな\n  い。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "侵害者の譲渡数量と権利者商品の単位利益を用いる損害算定が認められる。販売能力や販売できない事情等の調整は別途あるが、アが適切。",
    "basis": "商標法36条・38条・78条等",
    "choiceExplanations": {
      "ア": "販売可能数量等の法定条件のもとで、侵害品の数量×権利者の単位利益による算定が可能。",
      "イ": "故意の商標権侵害には刑事罰が科される場合がある。",
      "ウ": "使用料相当額は常に賠償額の上限ではない。より大きい損害を他の規定等で請求できる。",
      "エ": "事前警告は一般的な差止請求の必須要件ではなく、侵害のおそれに対する予防も請求できる。"
    },
    "explanationCoverage": "full",
