    "difficulty": 3,
    "question": "問29\n ア~エを比較して,特許権者の対応として,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許権を侵害されている特許権者は,特許庁に対して判定を求め,侵害品が特許権に係る特\n  許発明の技術的範囲に属するとの判定結果を得た後でなければ,侵害者に対して差止請求訴\n  訟を行うことができない。",
      "イ": "損害賠償請求訴訟において,特許権者は,特許権の侵害があったことを前提として侵害者と\n  の間で交渉した場合に決まるであろう額を考慮することはできない。",
      "ウ": "特許権者は,特許権を侵害するおそれがある者に対して差止請求訴訟を行うことができない。",
      "エ": "故意又は過失により特許権を侵害したことにより特許権者の業務上の信用を害した者に対し\n  て,特許権者は,その業務上の信用を回復すべく必要な措置をとるよう裁判所に請求するこ\n  とができる。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "故意・過失の特許侵害により業務上の信用が害された場合、信用回復に必要な措置を裁判所に請求できる。エが適切。",
    "basis": "特許法71条・100条・102条・106条",
    "choiceExplanations": {
      "ア": "特許庁の判定は差止訴訟の必須の前提ではない。判定を先に取得せず提訴できる。",
      "イ": "侵害を前提に交渉したなら定まる対価等を、使用料相当損害の判断で考慮できる。",
      "ウ": "差止請求は侵害の停止に加えて予防も対象であり、侵害のおそれでも請求可能。",
      "エ": "信用回復措置を損害賠償に代え又は併せて請求できる制度がある。"
    },
