    "difficulty": 3,
    "question": "問30\n ア~エを比較して,著作者人格権に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "著作者人格権は,他人に譲ることや著作者が亡くなったときに相続をすることはできないが,\n  放棄をすることはできる。",
      "イ": "法人等の職務著作に該当する著作物は,その法人等が著作者人格権を有する。",
      "ウ": "共同著作物の著作者人格権は,著作者全員の合意がなくても行使することができる。",
      "エ": "映画の著作物の著作者人格権は,映画製作者に対し当該映画の著作物の製作に参加すること\n  を約束している者に帰属する。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "職務著作では法人等が著作者であり、人格権も法人等に帰属する。イが適切。財産権の譲渡・映画製作者への帰属とは区別する。",
    "basis": "著作権法15条・16条・59条・64条",
    "choiceExplanations": {
      "ア": "一身専属の人格権は譲渡・相続できない。権利を行使しない特約と、権利そのものを自由に放棄できるとの断定は異なる。",
      "イ": "法人等の職務著作が成立すれば、その法人等が著作者人格権を有する。",
      "ウ": "共同著作物の人格権の行使には著作者全員の合意が必要。合意の拒絶にも制約がある。",
      "エ": "映画の人格権は全体的形成に創作的に寄与した著作者等に帰属する。製作参加を約束した者全員に当然帰属するわけではない。"
    },
