    "question": "問31\n ア~エを比較して,意匠登録出願後の手続に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "意匠登録出願後3年以内に出願審査請求をする必要がある。",
      "イ": "図面の補正が要旨の変更に該当するとして審査官によってその補正が却下された場合の決定\n  に対する不服申立ては,拒絶査定不服審判の請求とともにしなければならない。",
      "ウ": "意匠登録出願に対する審査官からの拒絶理由の通知に対しては,意見書若しくは手続補正書,\n  又はその双方を提出することができる。",
      "エ": "秘密意匠の請求は,意匠登録出願後には行うことができない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "意匠の拒絶理由通知にも、意見書、手続補正書又は両方で対応できる。ウが適切。特許特有の審査請求制度等を意匠へ持ち込まない。",
    "basis": "意匠法14条・17条の2・47条等",
    "choiceExplanations": {
      "ア": "意匠には特許と同じ審査請求制度はなく、出願について審査される。",
      "イ": "意匠の補正却下決定に対しては独立の不服審判の制度がある。拒絶査定不服審判との同時請求が必須ではない。",
      "ウ": "指定期間内に反論の意見書や適法な補正書を提出でき、双方の提出も可能。",
      "エ": "秘密意匠の請求は出願時だけでなく、所定の最初の登録料納付時にも行える。"
    },
