    "difficulty": 3,
    "question": "問32\n ア~エを比較して,職務発明等に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "企業は,従業者のした職務発明について,発明完成と同時に特許を受ける権利を取得するこ\n  とを,契約や勤務規則等において予め定めることができる。",
      "イ": "同一企業内で異動前の職務に属する発明を異動後の部署で完成させた場合は職務発明となる\n  が,企業在籍時の職務に属する発明を退職後に完成させた場合は退職前の企業の職務発明と\n  はならない。",
      "ウ": "実用新案法においては,特許法上の職務発明に係る規定が準用されており,実用新案登録出\n  願に係る考案に対しても,同規定が適用される。",
      "エ": "2人の者が共同で発明をしたときに,一方の者の発明が職務発明となり他方の者の発明がい\n  わゆる自由発明となる場合はない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "共同発明でも、各発明者の使用者・職務との関係は別々に判断する。一方が職務発明、他方が自由発明という場合を否定するエが不適切。",
    "basis": "特許法35条、実用新案法11条",
    "choiceExplanations": {
      "ア": "職務発明について、契約・勤務規則等で使用者に特許を受ける権利を原始帰属させる定めができる。",
      "イ": "同一企業内の異動では過去の職務も考慮する。一方、退職後に新たに完成した発明まで元企業の従業者としての職務発明と当然には扱わない。",
      "ウ": "実用新案の職務考案にも特許法の職務発明の規定が準用される。",
      "エ": "職務発明かどうかは各人の業務・職務等で判断される。共同発明者全員が同じ分類になるとは限らない。"
    },
