    "sharedCase": "",
    "choices": {
      "ア": "パリ条約は,出願,先行技術調査及び審査に関する合理化と,これらに関する技術情報の普\n  及について定めた条約である。",
      "イ": "同盟国でした最初の特許出願に基づいて12カ月以内に優先権を主張して他の同盟国におい\n  て特許出願をすれば,最初の出願日に特許出願したものと同様の効果が得られる。",
      "ウ": "優先権を主張して取得した特許は,優先権の主張の基礎とされた特許出願に係る特許が無効\n  にされた場合であっても,自動的に無効にされることはない。",
      "エ": "パリ条約では,同盟国の国民は,内国民に課される条件及び手続に従う限り,内国民と同一\n  の保護を受け,かつ,自己の権利の侵害に対し内国民と同一の法律上の救済を与えられる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "出願・調査・審査の合理化等はPCTの制度の説明に対応する。パリ条約の主要原則と混同したアが不適切。",
    "basis": "パリ条約2条・4条・4条の2、PCTの目的",
    "choiceExplanations": {
      "ア": "パリ条約は内国民待遇、優先権、特許独立等を定める。国際出願手続の合理化を担うPCTとは異なる。",
      "イ": "特許の優先期間12か月内の優先権主張で、所定の事項について最初の出願日に基づく効果が得られる。",
      "ウ": "各国特許の独立により、優先基礎の特許が無効になっても他国特許は自動的に無効にならない。",
      "エ": "内国民待遇として、同盟国国民は原則内国民と同じ保護・救済を受ける。"
    },
