    "question": "問34\n ア~エを比較して,特許料に関して,最も不適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "特許権を発生させるためには,特許査定の謄本が送達されてから所定期間内に特許料を納付\n  しなければならない。",
      "イ": "最初の特許料は,第1年から第2年分の特許料をまとめて支払わなくてはならない。",
      "ウ": "特許庁長官は,特許出願人の請求により最初の特許料の納付期間を30日間延長することが\n  できる。",
      "エ": "特許料を納付する者がその責めに帰することができない理由により特許料を納付することが\n  できない場合には,その後に特許料を納付することができる場合がある。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "設定登録のためには第1年から第3年までの特許料をまとめて納付する。2年分とするイが不適切。",
    "basis": "特許法108条・112条等",
    "choiceExplanations": {
      "ア": "特許査定後、所定期間内に設定登録のための特許料を納付する必要がある。",
      "イ": "最初にまとめて払うのは第1年から第3年分であり、第2年分までではない。",
      "ウ": "出願人の請求による30日の納付期間延長の制度がある。",
      "エ": "期限徒過後の納付・回復が認められる場合があるが、所定の理由・期間・手続を満たす必要がある。"
    },
    "explanationCoverage": "full",
    "calculationSteps": [],
    "hasImage": false,
