    "question": "問35\n ア~エを比較して,著作隣接権を有する者に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "放送事業者と有線放送事業者は,複製権を有するが送信可能化権は有しない。",
      "イ": "レコード製作者は,商業用レコードを用いた放送に関し,二次使用料を請求する権利を有す\n  る。",
      "ウ": "実演家は,実演を公表する時期や方法等を決定できる権利である公表権を有する。",
      "エ": "著作隣接権者は,著作隣接権の全部又は一部を譲渡することができない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "レコード製作者は商業用レコードの放送等に関し二次使用料を受ける権利を持つ。イが適切。隣接権も財産権として譲渡が可能。",
    "basis": "著作権法90条の2・90条の3・97条・99条の2・100条の4・103条",
    "choiceExplanations": {
      "ア": "放送・有線放送事業者には送信可能化権も認められる。複製権だけではない。",
      "イ": "商業用レコードを用いた放送等について、レコード製作者の二次使用料の制度がある。",
      "ウ": "実演家人格権は氏名表示権・同一性保持権で、著作者と同じ公表権を持つわけではない。",
      "エ": "財産権としての隣接権は全部又は一部を譲渡できる。実演家人格権との区別が必要。"
    },
