    "difficulty": 3,
    "question": "問36\n ア~エを比較して,商標法に規定する登録異議の申立て又は審判に関して,最も適切と考えら\nれるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "何人も,商標法第51条(不正使用取消審判)に規定する審判を請求することができる。",
      "イ": "登録商標が3年間継続して使用されていない期間があれば,現在その登録商標が使用されて\n  いても,その登録商標に対して商標法第50条(不使用取消審判)に規定する審判を請求す\n  ることができる。",
      "ウ": "何人も,商標登録を無効にすることについて審判を請求することができる。",
      "エ": "利害関係人に限り,登録異議の申立てをすることができる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "商標権者の不正使用を理由とする取消審判は何人も請求できる。アが適切。無効審判、異議申立て、不使用取消しは請求人や要件が異なる。",
    "basis": "商標法43条の2・46条・50条・51条",
    "choiceExplanations": {
      "ア": "51条の不正使用取消審判には利害関係人に限る請求人の制限がない。",
      "イ": "不使用取消しで問うのは所定の基準における継続3年以上の不使用。過去に一度3年不使用だっただけでは足りない。",
      "ウ": "商標登録無効審判の請求は利害関係人に限られる。何人も請求できるとはいえない。",
      "エ": "登録異議申立ては期間内であれば何人もでき、利害関係人に限定されない。"
    },
