    "difficulty": 3,
    "question": "問37\n ア~エを比較して,海外における他社の特許調査を行うために有効な手段として,最も不適切\nと考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "海外の特許庁が提供しているデータベースを利用する",
      "イ": "特許情報プラットフォーム(J-PlatPat)を利用する",
      "ウ": "国際調査機関に国際調査を依頼する",
      "エ": "海外の特許事務所に特許調査を依頼する"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "国際調査はPCT国際出願に伴う所定の調査で、他社の海外特許の一般調査を任意に依頼する窓口ではない。ウが不適切。",
    "basis": "PCT国際調査制度、J-PlatPat",
    "choiceExplanations": {
      "ア": "各国特許庁のデータベースは公報や権利情報の調査に利用できる。",
      "イ": "J-PlatPatは所定の外国特許情報等も扱い、調査手段として利用できる。収録範囲は確認する。",
      "ウ": "国際調査機関のPCT調査と、任意の第三者特許調査の依頼を混同している。",
      "エ": "海外の特許事務所へ現地の公報・権利状況等の調査を依頼する方法は有効。"
    },
