    "difficulty": 3,
    "question": "問38\n ア~エを比較して,弁理士の業務に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "弁理士は,特許無効審判の請求に関して相談を受け,対処方針等の助言を与えた後であって\n  も,当該特許無効審判において相手方となる特許権者の代理人となることができる。",
      "イ": "弁理士が特許出願の代理を業として行う場合,弁理士法人として行う必要がある。",
      "ウ": "弁理士は,弁護士と共同でなくても,裁判所において拒絶査定不服審判の審決の取消しを求\n  める訴訟の代理人となることができる。",
      "エ": "弁理士でなければ,特許原簿への登録の申請手続を業として行うことはできない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "審決取消訴訟では弁理士が単独で訴訟代理人となれる。特定侵害訴訟での弁護士との共同受任の条件とは異なり、ウが適切。",
    "basis": "弁理士法6条・31条・75条",
    "choiceExplanations": {
      "ア": "対立当事者から助言を求められた事件等には利益相反の職務制限がある。",
      "イ": "弁理士は個人としても出願代理を業務にでき、弁理士法人であることは必須でない。",
      "ウ": "拒絶査定不服審判の審決取消訴訟は、弁理士が弁護士との共同でなくても代理できる。",
      "エ": "登録申請には法律上の他の資格者等に関する例外がある。弁理士以外は一切できないとする断定は誤り。"
    },
