    "difficulty": 3,
    "question": "問39\n ア~エを比較して,著作権に関して,最も適切と考えられるものはどれか。",
    "sharedCase": "",
    "choices": {
      "ア": "上映権とは,映画特有の配給制度に応じて設けられた,他人に無断で公に上映されない権利\n  であり,映画の著作物にのみ認められる。",
      "イ": "複製権における複製とは,著作物を有形的に再製することをいい,著作物をインターネット\n  で配信することもこれに含まれる。",
      "ウ": "上演権・演奏権とは,自己の著作物を他人に無断で公に上演・演奏されない権利であるが,\n  「生」の上演・演奏に限定され,上演・演奏を録音・録画したものを再生することは含まれ\n  ない。",
      "エ": "譲渡権とは,著作物(映画の著作物を除く)の原作品又は複製物を他人に無断で公衆に譲渡\n  されない権利であるが,著作権者から他の人に譲渡された著作物の原作品又は複製物をその\n  後公衆に譲渡する行為について,その効力は及ばない。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "適法に譲渡された原作品等の再譲渡では、譲渡権が消尽する。エが適切。上映・公衆送信・録音物の再生はそれぞれ定義を確認する。",
    "basis": "著作権法2条・22条・22条の2・26条の2",
    "choiceExplanations": {
      "ア": "上映権は映画に限定されず、他の著作物の公の上映にも認められる。映画の配給に関する頒布権と区別する。",
      "イ": "配信は公衆送信等の行為。保存等で複製が伴う場合はあるが、配信そのものを有形的再製と同一視しない。",
      "ウ": "上演・演奏には所定の録音・録画物の再生等も含まれ、生だけに限定されない。",
      "エ": "権利者から適法に譲渡された原作品・複製物の再譲渡には、その譲渡権は及ばない。"
    },
