    "question": "1 X社は,医療用ロボットを研究開発するベンチャー企業である。X社の開発者甲と,大手精\n 密機器メーカーY社の研究開発部の研究員乙は,新たな医療用ロボットに係る発明A,発明B\n を共同で発明した。Y社の知的財産部の部員丙は,この共同研究開発の成果であるこれらの発\n 明について特許出願をすることを検討している。丙は,発言1~2をしている。なお,X社と\n Y社の間には,発明の取扱に関して何ら取決めはないものとする。\n発言1 「Y社は,職務発明の特許を受ける権利について従業者から取得する旨を,予め就業規\n     則において定めています。この場合,発明Aに関する特許を受ける権利を乙からY社\n     に移転するために,特許を受ける権利の承継手続は不要です。」\n発言2 「X社は,発明Bの実施条件について,社内で意見がまとまらず,発明Bに係る特許出\n     願について,難色を示しています。しかしながら,甲は,発明Bに係る特許出願につ\n     いて賛成しているので,X社の社内の意見がまとまるのを待たずに,Y社が発明Bに\n     係る特許出願を単独で出願しても問題はありません。」\n 以上を前提として,問1~問4に答えなさい。\n\n問1\n 発言1について,適切と考えられる場合は「○」を,不適切と考えられる場合は「×」を,選\nびなさい。",
