    "sharedCase": "3 広告会社X社の営業部の部員甲が,コンテンツの利用方法についてX社の法務部の部員乙に\n 質問をしている。発言1~2は甲の発言である。\n発言1 「先日,近所のスケートリンクでアイスショーが行われていて,元スケート選手の丙が\n     古典音楽家バッハの曲に合わせて自由に滑っていました。この様子をスマートフォン\n     で動画撮影したので,自分のブログにアップロードして紹介することを考えています。\n     ブログは,営利を目的とせず個人的な趣味でやっているものです。この場合,著作権\n     法上,問題はありませんよね。」\n発言2 「地元に新しくショッピングセンターが開店することになったそうです。ショッピング\n     センターを宣伝する営利の目的で,地元の音楽大学の学生を招いて,若手の作曲家丁\n     がドラマのテーマソングとして作曲した曲を演奏してもらうライブを企画しているそ\n     うです。ライブでは客は無料で演奏を聴くことができて,学生には演奏料を支払う予\n     定はありません。また,ライブ演奏だけで録音やネット配信等は行いません。この場\n     合,著作権法上,問題はありませんよね。」\n 以上を前提として,問9~問12に答えなさい。",
