      "イ": "わが社は東京証券取引所のプライム市場に属しているため,コーポレートガバナンス・コー\n  ドの対象外である。そのため新規事業の開始の際の知的財産権の侵害のリスクがある場合で\n  あっても,知的財産担当取締役や取締役会にまでは報告する必要はない。",
