    "question": "4 問13~問33に答えなさい。\n\n問15\n 検査機器メーカーX社は,画像処理装置Aを製造販売している。Y社は自己の有する特許権P\nに基づいて,X社の画像処理装置Aの製造販売行為に対して,侵害訴訟を提起した。X社の知的\n財産部の部員は,特許権Pに係る特許発明の内容を検討している。ア~エを比較して,無効理由\nを有する特許発明として,最も適切と考えられるものを1つ選びなさい。",
