    "officialAnswerNumber": "ア",
    "explanation": "コンピュータ言語それ自体は人為的な取決めで、自然法則を利用した技術的思想の創作ではない。アが発明該当性を欠くものとして適切。",
    "basis": "特許法2条・29条・123条",
    "choiceExplanations": {
      "ア": "工程を表すための言語そのものは規則・約束であり、特許法上の発明に該当しない。",
      "イ": "具体的な情報処理として自然法則利用等の要件を満たす画像処理方法は特許対象になり得る。",
      "ウ": "技術的な手段を備えた画像処理装置は物の発明となり得る。",
      "エ": "具体的な処理部を備えるコンピュータ装置も技術的構成として特許対象になり得る。"
    },
    "explanationCoverage": "full",
