    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "意匠法4条・7条、複数意匠の一括出願手続"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問16\n 家具メーカーX社は,開発中の机の試作品A及び試作品Bを展示会に出品した。試作品A及び\n試作品Bが好評であったので,製品化が決定され,意匠登録出願を検討している。ア~エを比較\nして,X社の知的財産部の部員の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "X社は,試作品A及び試作品Bに係る意匠について,1通の願書により複数の意匠登録出願\n  をまとめて出願し,意匠登録を受けることができる。",
      "イ": "X社は,試作品Aに係る意匠について,新規性喪失の例外の手続をして意匠登録出願する場\n  合には,展示会で試作品Aに係る意匠を出品した日から9カ月以内に,意匠登録出願をしな\n  ければならない。",
      "ウ": "X社が,試作品A及び試作品Bについて,新規性喪失の例外の手続をして,各々について意\n  匠登録出願をする場合には,同日に出願しなければならない。",
      "エ": "X社が,試作品Aに係る意匠について,新規性喪失の例外の手続をして意匠登録出願をした\n  場合,試作品Aを展示会に出品した日が意匠登録出願の出願日とされる。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "複数の意匠登録出願を一つの願書でまとめて提出する手続が利用できる。各意匠が別出願として扱われる点を区別してアを選ぶ。",
    "basis": "意匠法4条・7条、複数意匠の一括出願手続",
    "choiceExplanations": {
      "ア": "複数意匠の一括出願が可能。ただし複数の意匠が一つの登録権利に自動的に合体するものではない。",
      "イ": "新規性喪失の例外に関する出願期間は原則公開から1年。9か月という一般期限ではない。",
      "ウ": "各公開行為・例外要件に対応して手続すればよく、同日出願が一般的な必須条件ではない。",
      "エ": "例外適用で出願日が展示日に遡るわけではない。優先権のような日付遡及と区別する。"
    },
