    "examDate": "2026-03-08",
    "qNumber": 17,
    "type": "multiple-choice",
    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "特許法29条1項"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問17\n 自動車メーカーX社の技術者甲は,新しい電動パワーステアリング技術に関する発明Aを創作\nし,特許出願を計画している。X社の知的財産部の部員乙は,発明Aに関する新規性について調\n査をした。ア~エを比較して,乙の考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "競合企業Y社が,発明Aとほぼ同一の技術についてドイツでのみ特許権を取得し,特許公報\n  が公開されている。しかし海外の特許公報なので,新規性は否定されない。",
      "イ": "甲は,X社の外注企業W社に対して発明Aに関する技術説明会を開催した。しかしW社とは\n  秘密保持契約を締結した上で開催したので,新規性は否定されない。",
      "ウ": "自動車業界の専門誌に,X社の発明Aが掲載され,オンラインで有料購読可能になっている。\n  しかし無料公開ではないので,新規性は否定されない。",
      "エ": "甲は,自身のSNSに発明Aに関する投稿をし,一般に公開された。しかし社外の技術者に\n  閲覧された可能性は低いので,新規性は否定されない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "秘密保持義務の下で行われた技術説明は通常公然知られた状態を生じさせない。イが適切。外国公報、有料購読、SNS公開は別の扱いとなる。",
    "basis": "特許法29条1項",
    "choiceExplanations": {
      "ア": "外国の公開特許公報も先行技術になり得る。日本で公開されていないことだけでは回避できない。",
      "イ": "秘密保持契約により非公開を保った説明では、新規性を失わない。義務や実際の管理状況は確認する。",
      "ウ": "有料でも一般に購読可能な専門誌は公衆が知り得る資料。無料公開が必須ではない。",
      "エ": "一般公開のSNS投稿は閲覧可能となったことが問題。閲覧人数が少ないだけで公知性を否定できない。"
    },
