    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問18\n X社は,品種Aについて種苗法に基づく品種登録を受けた。ア~エを比較して,X社の担当者\nの考えとして,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "わが社から品種Aの種苗を購入した者が,その種苗を無断で第三者に譲渡する行為は,わが\n  社の育成者権を侵害する。",
      "イ": "品種Aの育成方法に係る特許権を有するY社が,その特許発明に基づいて品種Aを生産する\n  行為は,わが社の育成者権を侵害する。",
      "ウ": "品種Aを試験又は研究のために利用する行為に対しては,育成者権を行使できない。",
      "エ": "品種Aは,永年性植物であるので,育成者権の存続期間は,品種登録の日から20年間であ\n  る。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "育成者権は新品種育成その他の試験・研究のための利用等には及ばない。ウが適切。譲渡後の消尽や先願の生産方法特許との利用関係にも例外がある。",
    "basis": "種苗法21条等",
    "choiceExplanations": {
      "ア": "適法に譲渡された種苗の再譲渡には、原則として権利の消尽が働く。購入者の再譲渡を一律に侵害とできない。",
      "イ": "先願の生産方法特許との利用関係等では育成者権の効力が及ばない場合がある。特許に基づく生産を一律に侵害とする断定は誤り。",
      "ウ": "試験・研究のための利用には育成者権の効力の制限がある。",
      "エ": "永年性植物の存続期間は登録から30年であり、20年ではない。"
    },
