    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "著作権法16条"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問19\n 新人映画監督の甲は,漫画家乙が描いた漫画Aを映画化した。映画製作にあたり,資金繰りに\n難航していたため,甲の友人である丙が不足する資金を提供し,また,劇中に使用する効果音の\n創作も行った。映画の脚本は甲の知人丁が書いた。ア~エを比較して,当該映画の著作物の著作\n者となり得る者として,最も適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "甲と乙と丙と丁",
      "イ": "甲と丙と丁",
      "ウ": "甲と丁",
      "エ": "甲"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "映画の著作者は制作・監督・演出・撮影等によって全体的形成へ創作的に寄与した者。原作、脚本、資金提供、効果音だけの関与と区別し、本件では監督甲を選ぶ。",
    "basis": "著作権法16条",
    "choiceExplanations": {
      "ア": "原作者・脚本家・資金や効果音の提供者をすべて映画自体の著作者に含めるのは誤り。",
      "イ": "丙の資金提供や効果音、丁の脚本のみでは映画の全体的形成への寄与に当然該当しない。",
      "ウ": "丁は脚本の著作者になり得るが、脚本だけを根拠に映画自体の著作者に加えない。",
      "エ": "映画監督として全体的形成に創作的に寄与した甲が該当する。原作・脚本等の権利は別途存続する。"
    },
    "explanationCoverage": "full",
    "calculationSteps": [],
