    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問21\n ア~エを比較して,知的財産の譲渡契約についてのX社の知的財産部の部員の考えとして,最\nも不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "譲渡契約の調印者は,できれば代表取締役が望ましいが,知的財産に関する契約の締結につ\n  いて権限を有する執行役員でも問題はない。",
      "イ": "特許や商標の譲渡に関する交渉の場合,生成AIを使用した無償のアプリケーションが作成\n  した契約書をそのまま使用した場合であっても,交渉する双方の署名押印があり,意思表示\n  が合致しているのであれば,契約の効力は発生する。",
      "ウ": "契約の法的な証拠としての価値という観点からは,直筆でサインしている署名と,ゴム印で\n  氏名を印したような記名とでは,証拠としての価値はほとんど変わらない。",
      "エ": "契約は内容が確定できる必要があり,譲渡の対象となる特許や商標が全く特定されていない\n  場合,有効な契約とは認められない。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "本人の自筆署名と、ゴム印等の記名のみでは真正成立の推定等の証拠上の扱いに違いがある。ほとんど変わらないとするウが不適切。",
    "basis": "契約成立・代理権、民事訴訟法228条",
    "choiceExplanations": {
      "ア": "適切な契約締結権限がある者は署名でき、代表取締役本人に限られない。",
      "イ": "AI作成の文案でも当事者の合意等の成立要件を満たせば契約は成立し得る。内容の正確性や登記による権利移転は別途確認する。",
      "ウ": "自筆署名と単なる記名は証拠上同じではない。押印・本人性等の条件も確認する。",
      "エ": "譲渡対象を確定できないなら合意内容が定まらない。対象の特許・商標等を特定する必要がある。"
    },
