    "round": 53,
    "year": 2026,
    "season": "spring",
    "section": "practical",
    "session": "practical",
    "examDate": "2026-03-08",
    "qNumber": 22,
    "type": "multiple-choice",
    "category": "知的財産管理技能検定2級",
    "topicTags": [
      "不正競争防止法2条1項3号・営業秘密の各類型・19条"
    ],
    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問22\n 金属加工メーカーX社の知的財産部の部員が,新しく発売した,新規形状のステンレス製の収\n納用のラックAについて説明を行っている。ア~エを比較して,部員の考えとして,最も不適切\nと考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "Y社がラックAと酷似しているラックBを製造販売していることが判明し,調査したところ,\n  X社でラックAの製造装置の設計開発をしていた研究者甲が,6カ月前にX社を退社し,す\n  ぐにY社に入社していることがわかった。甲がX社の在籍時に担当していた製造装置の設計\n  図をそのまま流用しない限り,早期にラックBを製造するのは困難である。しかしながら,\n  退社後ということもあり,X社は,不正競争防止法による保護を受けられる場合はない。",
      "イ": "X社は,ラックAについて,新たな商品名Cとして販売を始めた。まだ発売されたばかりで\n  あるが,テレビで宣伝しているので,商品名Cもそれなりに知られている。商品名Cについ\n  て商標登録出願をしたところ,極めて簡単でありふれた名称であるとして商標登録を受けら\n  れなかったが,不正競争防止法による保護を受けられる場合はある。",
      "ウ": "ラックAの形状に関しては,意匠法及び不正競争防止法第2条第1項第3号(商品形態模倣\n  行為)による保護が可能である。その場合,不正競争防止法で保護される期間は,意匠法で\n  保護される期間よりも短いので注意が必要である。ラックAに関しては,日本国内で最初に\n  販売してから2年後には新規デザインの次世代製品に替わる予定であり,大きな問題はない。",
      "エ": "ラックAの形状が,W社が先に販売していたラックDと類似していることが判明した。X社\n  が模倣したわけではなく,あくまでも偶然に似てしまったものであるから不正競争防止法第\n  2条第1項第3号(商品形態模倣行為)に該当するものではないが,X社のオリジナリティ\n  確保のため,ラックAのデザイン変更を検討する。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "退職者による営業秘密の不正使用も不正競争になり得る。退職後だから保護できないとするアが不適切。",
    "basis": "不正競争防止法2条1項3号・営業秘密の各類型・19条",
    "choiceExplanations": {
      "ア": "設計図が営業秘密の要件を満たし、不正な使用等があれば退職者や転職先の行為も対象となり得る。",
      "イ": "商標登録できない名称でも、商品等表示の周知性・混同等の要件を満たせば不正競争防止法の保護があり得る。",
      "ウ": "商品形態模倣の保護は国内初販売から原則3年で、現行意匠権の通常の存続期間より短い。",
      "エ": "形態模倣には他の商品形態への依拠等が必要。独立開発で偶然似たことだけではこの模倣類型にならない。"
    },
