    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問23\n 写真家甲は,これまで撮影してきた写真について利用許諾をするか,著作権を譲渡するかにつ\nいて検討している。ア~エを比較して,甲の考えとして,最も適切と考えられるものを1つ選び\nなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "利用許諾の登録をしなければ,利用許諾の効力は発生しない。",
      "イ": "譲渡の登録をしなければ,譲渡の効力は発生しない。",
      "ウ": "譲渡契約書に「すべての権利を譲渡する」と記載すると,甲の著作者人格権は消滅する。",
      "エ": "期間を決めて利用許諾をすることができる。"
    },
    "answer": "エ",
    "officialAnswerNumber": "エ",
    "explanation": "利用許諾では利用期間や方法を契約で決められる。エが適切。譲渡の登録や人格権の扱いを区別する。",
    "basis": "著作権法59条・63条・77条",
    "choiceExplanations": {
      "ア": "利用許諾の成立に登録は必須でない。",
      "イ": "譲渡の登録は第三者対抗要件で、当事者間の効力発生の必須条件ではない。",
      "ウ": "人格権は一身専属で、すべての権利を譲渡すると書くだけでは消滅・移転しない。",
      "エ": "一定の期間に限って許諾する契約を締結できる。期間後の扱いも定めておく。"
    },
