    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問24\n 音響機器メーカーX社の知的財産部の部員甲が,特許の調査方法について部員乙に説明してい\nる。ア~エを比較して,部員甲の発言として,最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "「特許調査をする際の注意点は,特許出願は,原則として出願日から1年6カ月経過しなけ\n   れば公開されないので,調査日から1年6カ月前までの間に出願された特許出願は,調査\n   できないことです。これは,特許情報プラットフォーム(J-PlatPat)に限らず,他の有\n   料特許データベースにおいても同様です。」",
      "イ": "「特許文献は,技術分野毎に分けられ,分類されています。分類には,世界共通の分類であ\n    るFI(File Index)や日本独自の分類であるFタームがあります。」",
      "ウ": "「すでに出願公開されている特許出願,又は登録されている特許を調査するには,特許情報\n   プラットフォーム(J-PlatPat)を利用することができます。」",
      "エ": "「特許調査をする際は,漏れをなくすために公開特許公報だけでなく登録後に発行される特\n   許掲載公報も調査する必要があります。」"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "世界共通の分類はIPC。FIはIPCを細分化した日本独自の分類であり、世界共通とするイが不適切。",
    "basis": "IPC・FI・Fターム、J-PlatPat",
    "choiceExplanations": {
      "ア": "原則18か月の出願公開まで未公開の情報は、有料DBでも通常調べられない。早期公開等の例外はある。",
      "イ": "FIは日本独自の分類。国際共通のIPCと区別する。Fタームも日本の検索分類である。",
      "ウ": "J-PlatPatで公開出願や登録特許の公報等を調査できる。",
      "エ": "公開公報だけでなく、公開前に登録された案件等も把握するため特許掲載公報を確認する。"
    },
