    "caseNumber": 4,
    "choices": {
      "ア": "発明Aは展示会で発表し公開されたので,特許出願Qの審査では,発明Aを記載した特許出\n  願Pが先行技術文献として引用される。",
      "イ": "発明Bが記載された特許出願Qが出願公開されるのは,特許出願Qの出願日から1年6カ月\n  後になる。",
      "ウ": "特許出願Qのうち,発明Bについては特許出願Qの出願日を基準に新規性等の審査が行われ\n  る。",
      "エ": "特許出願Qが特許権として登録された場合の存続期間は,特許出願Pの出願日から20年間\n  である。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "先のPに記載されていなかった改良発明Bには優先日の利益が及ばず、Qの出願日で新規性等を判断する。ウが適切。",
    "basis": "特許法41条・42条・64条・67条",
    "choiceExplanations": {
      "ア": "国内優先権の先のPが、当然に公開先行文献としてQを拒絶させるとはいえない。Pの取下げ擬制や優先効果を区別する。",
      "イ": "国内優先権を伴うQの公開は原則Pの日から1年6か月を基準とする。Qの日からではない。",
      "ウ": "Pにない新たなBの事項には優先効果がないため、Qの出願日を基準に判断する。",
      "エ": "通常の特許存続期間は後のQの出願日から20年。Pの優先日からではない。"
    },
