    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問27\n 家電機器メーカーX社は,電子レンジAに係る秘密意匠の意匠権Dを取得した。X社の知的財\n産部の部員が調査したところ,X社が電子レンジAを発売する直前になって,意匠権Dの秘密期\n間経過前において,ライバルメーカーのY社が,電子レンジAと類似する電子レンジBを製造販\n売していることがわかった。ア~エを比較して,部員の考えとして,最も適切と考えられるもの\nを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "意匠権Dの秘密期間を短縮することを考えているが,意匠権Dの設定登録後に,秘密期間を\n  短縮することはできない。",
      "イ": "秘密意匠であっても,電子レンジBが,意匠権Dに係る登録意匠の範囲に属することを確認\n  するために,特許庁に判定を請求することができる。",
      "ウ": "Y社に対して,意匠権Dの秘密期間経過後でなければ差止請求を行うことはできない。",
      "エ": "意匠権を侵害した者は,侵害行為について過失があったものと推定されるので,意匠権Dに\n  基づく権利行使において,Y社の過失を立証する必要はない。"
    },
    "answer": "イ",
    "officialAnswerNumber": "イ",
    "explanation": "秘密意匠でも特許庁の判定を請求できる。秘密期間中の差止めには証明書面による警告等の特別な条件があり、通常の過失推定も同じではない。",
    "basis": "意匠法14条・24条・37条3項・40条",
    "choiceExplanations": {
      "ア": "秘密期間は設定登録後にも所定の範囲で短縮等の請求が可能。",
      "イ": "秘密意匠だから技術的範囲に相当する意匠の範囲の判定制度が使えなくなるわけではない。",
      "ウ": "所定の証明書面を提示した警告等の条件を満たせば、秘密期間内でも差止請求が可能。",
      "エ": "秘密意匠には通常の意匠と同じ過失推定が適用されない。秘密である点の特則を確認する。"
    },
