    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問29\n 電線メーカーX社は,新たに設計開発した光ファイバーに関する特許出願をして,特許権Pを\n取得した。一方,光ファイバーメーカーY社は,光ファイバーAを独自に開発していた。なお,\n光ファイバーは要件によっては外為法(外国為替及び外国貿易法)におけるリスト規制の対象に\nなる可能性がある。ア~エを比較して,Y社の知的財産部の部員の考えとして,最も不適切と考\nえられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "光ファイバーAに係る特許権を取得するために必要最小限の技術を明細書に記載して外国に\n  特許出願することについては,外為法の許可は必要ない。",
      "イ": "光ファイバーAを製造販売する前に,外国にある企業へ光ファイバーAに係る技術の内容に\n  ついて情報提供する際には,外為法の許可の申請が必要となる場合がある。",
      "ウ": "光ファイバーAは,特許権Pに係る特許請求の範囲に記載された構成要素のすべてを備えて\n  はいない。したがって,光ファイバーAの製造販売開始後にX社が特許権Pに基づいて侵害\n  訴訟を提起した場合であっても問題はない。",
      "エ": "特許権Pと,光ファイバーAは関連することがわかった。X社は,将来,光ファイバーAの\n  製造販売行為に対して,特許権Pに基づいて,侵害訴訟を提起してくる可能性が高いので,\n  光ファイバーAの実施行為が特許権Pの侵害とならないような設計変更が可能かを検討すべ\n  きである。"
    },
    "answer": "ウ",
    "officialAnswerNumber": "ウ",
    "explanation": "請求項の構成を完全に同一に備えなくても均等侵害の可能性がある。要素の相違だけで訴訟に問題がないとするウが不適切。",
    "basis": "特許権の均等侵害、外為法の技術提供規制",
    "choiceExplanations": {
      "ア": "外為法の技術提供規制には外国出願のための必要最小限の技術提供に関する例外がある。特許法の外国出願制限等とは別に確認する。",
      "イ": "外国企業へ規制対象技術を提供する場合、商品を販売する前でも許可が必要となる場合がある。",
      "ウ": "構成要素が違っても均等論の条件を満たせば侵害となり得る。文言差だけで安心できない。",
      "エ": "具体的な権利範囲と製品構成を比較し、侵害を回避できる設計変更を検討するのは適切。"
    },
