      "イ": "職務発明の規程がなくても、職務発明に関する使用者の法定通常実施権は成立し得る。",
      "ウ": "完成時のY社の業務・甲の職務との関係から、Y社が法定通常実施権を取得する。",
      "エ": "完成前に退職したX社の過去の職務だけを理由として、X社のみが取得するとはいえない。"
