    "difficulty": 3,
    "question": "4 問13~問33に答えなさい。\n\n問32\n 食品メーカーX社は,添加物Aに係る特許権Pを有する。特許権Pについては,Y社のみに添\n加物Aの製造販売に関する通常実施権が許諾されていた。X社の知的財産部の部員が調査したと\nころ,最近,W社が添加物Aと同一の添加物Bを製造販売していることがわかった。ア~エを比\n較して,部員の考えとして,最も不適切と考えられるものを1つ選びなさい。",
    "sharedCase": "4 問13~問33に答えなさい。",
    "caseNumber": 4,
    "choices": {
      "ア": "W社が製造した添加物Bを,V社が購入してV社が販売する行為は,特許権Pの侵害とはな\n  らないため,特許権侵害に係る警告書を送付する相手はW社に限られる。",
      "イ": "X社がW社に対して差止請求権を行使する場合には,事前に警告することは不要である。",
      "ウ": "特許権Pに係る特許請求の範囲に誤記があることを発見した場合,登録後であっても,誤記\n  の訂正をすることはできる。",
      "エ": "X社がY社に無断で特許権PをW社に移転しても,Y社の通常実施権の対抗力は有効である。"
    },
    "answer": "ア",
    "officialAnswerNumber": "ア",
    "explanation": "無許諾のW社の侵害品を購入して再販売するV社も、特許発明の譲渡として侵害となり得る。適法な権利者からの購入による消尽とは異なりアが不適切。",
    "basis": "特許法100条・99条・126条等",
    "choiceExplanations": {
      "ア": "侵害品の購入で特許権が消尽するわけではない。V社の再販売も権利行使の対象になり得る。",
      "イ": "差止請求の一般的要件に事前警告は含まれない。",
      "ウ": "登録後も所定の要件・手続により誤記訂正等を行う制度がある。",
      "エ": "通常実施権には当然対抗制度があり、特許権の移転後も新権利者へ対抗できる。"
    },
