      "イ": "著作権の侵害訴訟を提起するためには,その著作権に係る著作物について,著作権登録がさ\n  れていることが必要である。",
      "ウ": "著作権侵害の損害賠償請求訴訟において,侵害者の過失が推定されるため,侵害者の過失を\n  立証する必要はない。",
      "エ": "著作者の死亡と同時に著作者人格権も消滅するため,著作者死亡の後であれば,著作物を自\n  由に改変することができる。"
