    "sharedCase": "6 次の会話は,X社において特許協力条約(PCT)による国際出願を検討している発明者甲\n と知的財産部の部員乙のものである。問35~問37に答えなさい。\n甲 「外国で特許を取得したいので,国際出願を行いたいのですが,当然英語で出願書類を作成\n   する必要がありますよね。」\n乙 「国際出願を日本の特許庁に出願する場合は,その出願書類の作成に使用できるのは 1\n   です。」\n甲 「国際出願をすることによって,具体的にはどのような効果がありますか。」\n乙 「国際出願により, 2 に対して正規に国内出願したものとして扱われます。」\n甲 「国際出願をするとその出願について審査が行われますか。」\n乙 「すべての国際出願について特別の手続をしなくても国際調査が行われます。その結果,出\n   願人は 3 を受け取ることができます。」\n【語群VII】",
