    "explanation": "俳優丙を休憩中に無断で撮影し、その写真をブログに載せる場面では、本人の肖像に関する権利・利益への配慮が問題となる。空欄1は肖像権を表すウ。写真の著作権が撮影者に生じ得ることと、被写体本人の利益を害してよいことは別である。",
