    "explanation": "公園で撮影した動画に祭りのポスターが一時的・付随的に写り込む場面は、付随対象著作物の利用に関する権利制限の対象となる。設問の前提では空欄2はキ。ポスターを鑑賞の主目的として撮影する場合まで無条件に許されるという意味ではなく、写り込みの程度や利用目的等の要件を満たすことが必要である。",
    "basis": "著作権法30条の2・付随対象著作物の利用",
